function renderAutoEditBatchGladiaConcurrencyPlan() {
    const root = document.getElementById('autoedit-batch-gladia-concurrency-plan');
    if (!root) return;
    const primary = document.getElementById('autoedit-batch-transcription-primary')?.value || document.getElementById('transcription-primary')?.value || '';
    const taskCount = Math.max(1, Math.min(4, Number(document.getElementById('autoedit-batch-concurrency')?.value) || 1));
    const perTask = Math.max(1, Number(document.getElementById('autoedit-batch-gladia-per-task')?.value || document.getElementById('transcription-concurrency')?.value) || 1);
    const keyInput = document.getElementById('gladia-keys')?.value || '';
    const keys = [...new Set(String(keyInput).split(/\r?\n/).map(key => key.trim()).filter(Boolean))];
    const requested = taskCount * perTask;
    if (primary === 'gladia') {
        const effective = Math.min(requested, keys.length);
        const wait = Math.max(0, requested - effective);
        root.innerHTML = `<div class="ae-gladia-plan ${wait ? 'ae-gladia-plan-warn' : ''}"><strong>🔑 首选 Gladia：并发计划</strong><span>${taskCount} 个任务 × 每任务 ${perTask} 个片段 = 需要 ${requested} 个并发槽</span><b>已配置 ${keys.length} 个 Key → 实际同时转录 ${effective} 个片段${wait ? `，${wait} 个等待 Key` : ' ✓'}</b><small>任务卡显示每个片段实际使用的平台；首选平台失败时，该片段会单独切换到备用平台。</small></div>`;
        return;
    }
    if (primary === 'deepgram') {
        const effective = Math.min(requested, 50);
        root.innerHTML = `<div class="ae-gladia-plan"><strong>⚡ 首选 Deepgram：并发计划</strong><span>${taskCount} 个任务 × 每任务 ${perTask} 个片段 = 请求 ${requested} 路</span><b>Nova-3 预录音频项目上限 50 路 → 本批次 ${effective} 路</b><small>任务卡显示每个片段实际使用的平台；Deepgram 失败或超时时，该片段会单独切换到备用平台。</small></div>`;
        return;
    }
    root.innerHTML = `<div class="ae-gladia-plan ae-gladia-plan-warn"><strong>🌐 首选 Groq：并发计划</strong><span>${taskCount} 个任务 × 每任务 ${perTask} 个片段 = 请求 ${requested} 路</span><b>建议每任务保持 3–5 路；超过后可能被限流。</b><small>任务卡显示每个片段实际使用的平台；首选平台失败时会单独切换到备用平台。</small></div>`;
}
window.renderAutoEditBatchGladiaConcurrencyPlan = renderAutoEditBatchGladiaConcurrencyPlan;
function renderAutoEditBatchProgressOverview() {
    const root = document.getElementById('autoedit-batch-progress-overview');
    if (!root) return;
    const totalClips = autoEditBatchTasks.reduce((total, task) => total + (task.clips?.length || 0), 0);
    const analyzedTasks = autoEditBatchTasks.filter(task => task.result?.analysis_only);
    let recognized = 0, recognitionFailed = 0, matchingDone = 0, passed = 0, warnings = 0, matchFailed = 0, missing = 0;
    analyzedTasks.forEach(task => {
        const segments = getAutoEditBatchLiveResult(task)?.segments || [];
        segments.forEach(segment => {
            const text = String(segment.recognized_text || segment.matched_text || '');
            const failed = /转录失败|识别失败/.test(text) || /转录失败|识别失败/.test(String(segment.issue_reason || ''));
            if (failed || (!text.trim() && segment.status === 'error')) recognitionFailed++;
            else if (text.trim()) recognized++;
        });
        const item = getAutoEditBatchTaskSummary(task);
        matchingDone += item.total; passed += item.ready; warnings += item.warning; matchFailed += item.error; missing += item.missingBlocks;
    });
    const live = autoEditBatchTasks.filter(task => task.status === 'analyzing').map(task => task.progress || {});
    const transcribing = live.filter(p => p.stage === 'transcribe' || p.stage === 'start');
    const matching = live.filter(p => p.stage === 'matching');
    const recognitionComplete = Math.min(totalClips, recognized + recognitionFailed + transcribing.reduce((sum, p) => sum + (Number(p.current) || 0), 0));
    const pendingRecognition = Math.max(0, totalClips - recognitionComplete);
    const pendingMatch = Math.max(0, totalClips - matchingDone);
    const stage = (title, value, total, detail, color, active) => `<div class="ae-batch-progress-stage ${active ? 'is-active' : ''}"><div class="ae-batch-progress-stage-head"><strong>${title}</strong><span style="color:${color};">${value}/${total}</span></div><div class="ae-batch-progress-track"><i style="width:${total ? Math.min(100, Math.round(value / total * 100)) : 0}%;background:${color};"></i></div><div class="ae-batch-progress-detail">${detail}</div></div>`;
    if (!autoEditBatchTasks.length) { root.innerHTML = ''; return; }
    const state = matching.length ? '正在核对文案匹配' : (transcribing.length ? '正在进行语音识别' : (live.length ? '正在准备分析' : '等待开始分析'));
    root.innerHTML = `<section class="ae-batch-progress-overview"><div class="ae-batch-progress-heading"><strong>📊 本批次处理进度</strong><span>${state}</span></div><div class="ae-batch-progress-grid">${stage('素材片段', totalClips, totalClips, `${autoEditBatchTasks.length} 个任务文件夹 · 已配对 ${autoEditBatchTasks.filter(task => task.script?.trim()).length} 份文案`, '#94a3b8', false)}${stage('① 语音识别', recognitionComplete, totalClips, `成功 ${recognized} · 失败/空结果 ${recognitionFailed} · 待识别 ${pendingRecognition}`, recognitionFailed ? '#fb7185' : '#60a5fa', transcribing.length > 0)}${stage('② 文案匹配', matchingDone, totalClips, `通过 ${passed} · 警告 ${warnings} · 失败 ${matchFailed}${missing ? ` · 缺失文案 ${missing}` : ''} · 待匹配 ${pendingMatch}`, matchFailed ? '#fb7185' : (warnings || missing ? '#fbbf24' : '#51cf66'), matching.length > 0)}</div></section>`;
}

function formatAutoEditBatchLiveMessage(progress = {}, updatedAt = 0) {
    const total = Math.max(0, Number(progress.total) || 0);
    const current = Math.max(0, Number(progress.current) || 0);
    if (progress.stage === 'transcribe') {
        const active = Math.max(0, Number(progress.active_count) || 0);
        const queued = Math.max(0, Number(progress.queued_count) || 0);
        const provider = progress.provider_label ? ` · 平台 ${progress.provider_label}` : '';
        const waitedSeconds = updatedAt ? Math.floor((Date.now() - updatedAt) / 1000) : 0;
        const waitHint = waitedSeconds >= 15
            ? ` · 🟠 等待服务响应 ${waitedSeconds}s${waitedSeconds >= 45 ? '（可能网络慢或服务无响应，可停止后重试）' : ''}`
            : '';
        if (progress.clip_status === 'transcribing' || active > 0) {
            return `🟢 识别进行中${provider} · 已完成 ${current}/${total}${active ? ` · 正在识别 ${active}` : ''}${queued ? ` · 排队 ${queued}` : ' · 无排队'}${waitHint}`;
        }
        return `🟢 识别进行中${provider} · 已完成 ${current}/${total} · 正在等待下一片段${waitHint}`;
    }
    if (progress.stage === 'matching') {
        return `🟢 文案匹配进行中 · 已核对 ${current}/${total}`;
    }
    if (progress.stage === 'cancelled') return '⏹ 正在停止当前任务…';
    return progress.message || '正在准备分析…';
}
function autoEditBatchTaskHasIssues(task) {
    if (!task?.clips?.length) return true;
    const summary = getAutoEditBatchTaskSummary(task);
    return summary.error > 0 || summary.warning > 0 || summary.missingBlocks > 0 || task.status === 'error';
}
function autoEditBatchTaskIsHandledPassed(task) {
    if (!task?.clips?.length || autoEditBatchTaskHasIssues(task)) return false;
    const segments = task.reviewSegments || task.result?.review_segments || task.result?.segments || [];
    return Array.isArray(segments) && segments.some(hasAutoEditHumanReview);
}
function selectAllAutoEditBatchTasks() {
    setAllAutoEditBatchSendToReels(true);
}
function deselectAllAutoEditBatchTasks() {
    setAllAutoEditBatchSendToReels(false);
}
function selectAutoEditBatchPassedTasks() {
    let selected = 0;
    autoEditBatchTasks.forEach(task => {
        const allow = Boolean(task?.clips?.length) && !autoEditBatchTaskHasIssues(task);
        task.sendToReels = allow;
        if (allow) selected++;
    });
    persistAutoEditBatchReview();
    renderAutoEditBatchTasks();
    showToast(`已选择 ${selected} 个通过任务`, 'success');
}
function selectAutoEditBatchHandledPassedTasks() {
    let selected = 0;
    autoEditBatchTasks.forEach(task => {
        const allow = autoEditBatchTaskIsHandledPassed(task);
        task.sendToReels = allow;
        if (allow) selected++;
    });
    persistAutoEditBatchReview();
    renderAutoEditBatchTasks();
    showToast(`已选择 ${selected} 个修改后合格任务`, 'success');
}
function selectAutoEditBatchFailedTasks() {
    let selected = 0;
    autoEditBatchTasks.forEach(task => {
        const isIssue = autoEditBatchTaskHasIssues(task);
        task.sendToReels = isIssue;
        if (isIssue) selected++;
    });
    persistAutoEditBatchReview();
    renderAutoEditBatchTasks();
    showToast(`已选择 ${selected} 个未通过任务`, 'info');
}
function autoEditBatchTaskIsUnexported(task) {
    return !autoEditBatchExportIsCurrent(task);
}
function selectAutoEditBatchUnexportedTasks() {
    let selected = 0;
    autoEditBatchTasks.forEach(task => {
        const allow = Boolean(task?.clips?.length) && autoEditBatchTaskIsUnexported(task);
        task.sendToReels = allow;
        if (allow) selected++;
    });
    saveAutoEditWorkspaceState();
    renderAutoEditBatchTasks();
    showToast(`已选择 ${selected} 个未导出任务`, 'success');
}
function selectAutoEditBatchIssueFreeTasks() {
    return selectAutoEditBatchPassedTasks();
}
function deselectAutoEditBatchProblemTasks() {
    let deselected = 0;
    autoEditBatchTasks.forEach(task => {
        if (autoEditBatchTaskHasIssues(task) && task.sendToReels !== false) { task.sendToReels = false; deselected++; }
    });
    persistAutoEditBatchReview(); renderAutoEditBatchTasks();
    showToast(`已取消 ${deselected} 个有反馈问题的任务`, 'info');
}
function autoEditBatchTaskResultLabel(task) {
    if (!task?.clips?.length || task.status === 'skipped') return '空文件夹，已跳过';
    if (autoEditBatchExportIsCurrent(task)) return '已导出';
    if (task.status === 'analyzing') return '分析中';
    if (task.status === 'error') return `处理失败${task.message ? `：${task.message}` : ''}`;
    const summary = getAutoEditBatchTaskSummary(task);
    if (summary.error || summary.warning || summary.missingBlocks) {
        const issues = [summary.error ? `${summary.error} 个失败` : '', summary.warning ? `${summary.warning} 个警告` : '', summary.missingBlocks ? `${summary.missingBlocks} 处待处理文案` : ''].filter(Boolean);
        return `待处理问题：${issues.join('、')}`;
    }
    // 打开列表审核也会保存一份快照，不能仅凭 reviewed 状态就宣称“已处理”。
    if (task.status === 'reviewed' && autoEditBatchTaskIsHandledPassed(task)) return '已人工处理，待导出';
    if (task.status === 'reviewed') return '审核已保存，匹配通过';
    if (task.result?.analysis_only) return '分析通过，待导出';
    return task.message || '待分析';
}
async function copyAutoEditBatchTaskResults() {
    if (!autoEditBatchTasks.length) return showToast('目前没有批量任务', 'info');
    const text = autoEditBatchTasks.map(task => `${String(task.outputName || task.name || '未命名任务').trim()}\t${autoEditBatchTaskResultLabel(task)}`).join('\n');
    try {
        await navigator.clipboard.writeText(text);
    } catch (_) {
        const textarea = document.createElement('textarea');
        textarea.value = text; textarea.style.position = 'fixed'; textarea.style.opacity = '0';
        document.body.appendChild(textarea); textarea.select(); document.execCommand('copy'); textarea.remove();
    }
    showToast(`已复制 ${autoEditBatchTasks.length} 个任务的处理结果`, 'success');
}
function setAllAutoEditBatchSendToReels(checked) {
    autoEditBatchTasks.forEach(task => { task.sendToReels = Boolean(checked); });
    persistAutoEditBatchReview();
    renderAutoEditBatchTasks();
    showToast(checked ? `已勾选 ${autoEditBatchTasks.length} 个任务参与导出` : `已取消 ${autoEditBatchTasks.length} 个任务的导出`, 'success');
}
// 这些按钮在 HTML 内联 onclick 中调用。显式挂到 window，避免热启动后
// 脚本作用域变化导致“点了没有反应”。
window.setAllAutoEditBatchSendToReels = setAllAutoEditBatchSendToReels;
window.updateAutoEditBatchSendToReels = updateAutoEditBatchSendToReels;
window.selectAutoEditBatchIssueFreeTasks = selectAutoEditBatchIssueFreeTasks;
window.selectAutoEditBatchHandledPassedTasks = selectAutoEditBatchHandledPassedTasks;
window.deselectAutoEditBatchProblemTasks = deselectAutoEditBatchProblemTasks;
window.copyAutoEditBatchTaskResults = copyAutoEditBatchTaskResults;

function setAutoEditBatchTaskScript(task, value) {
    const nextScript = String(value || '');
    if (task.script === nextScript) return;
    task.script = nextScript;
    // 分析结果与当时的文案一一绑定。文案改动后禁止继续使用旧时间线。
    if (task.result || task.reviewSegments) {
        task.result = null;
        task.reviewSegments = null;
        task.reelsTransferError = '';
        task.status = task.clips?.length ? 'waiting' : 'error';
        task.message = task.clips?.length ? '文案已修改，请重新分析' : '没有视频';
        task.exportSignature = '';
        task.exportedAt = '';
    }
}

function getAutoEditBatchMatchSummary(data) {
    const segments = Array.isArray(data?.segments) ? data.segments : [];
    const supplied = data?.match_summary || {};
    // 已关闭的重复片段和开场钩子不再参与“待处理”统计；它们是人工已处理的
    // 审核动作。此前仅忽略 review_acknowledged，导致重复已排除后仍显示未处理。
    const isPending = segment => segment?.enabled !== false && segment?.is_hook !== true && segment?.review_acknowledged !== true;
    const isRisk = segment => segment?.status === 'warning' || segment?.status === 'error' || Number(segment?.similarity) < 75;
    const count = status => segments.filter(segment => segment?.status === status && isPending(segment)).length;
    const handled = segments.filter(segment => !isPending(segment) && isRisk(segment)).length;
    return {
        total: Number.isFinite(Number(supplied.total)) ? Number(supplied.total) : segments.length,
        ready: segments.length ? count('ready') : (Number(supplied.ready) || 0),
        warning: segments.length ? count('warning') : (Number(supplied.warning) || 0),
        error: segments.length ? count('error') : (Number(supplied.error) || 0),
        handled,
        // missing_blocks can be resolved interactively during review. Prefer the
        // live list so a processed placeholder is reflected immediately instead
        // of continuing to show the original backend count.
        missingBlocks: Array.isArray(data?.missing_blocks)
            ? data.missing_blocks.filter(block => !block.review_assignment).length
            : (Number.isFinite(Number(supplied.missing_blocks)) ? Number(supplied.missing_blocks) : 0),
    };
}

function getAutoEditBatchFailureBreakdown(data) {
    const segments = Array.isArray(data?.segments) ? data.segments : [];
    const isTranscriptionFailure = segment => {
        const evidence = `${segment?.recognized_text || ''} ${segment?.matched_text || ''} ${segment?.issue_reason || ''}`;
        return /转录失败|识别失败|未获得识别|未返回有效文字|空结果/.test(evidence);
    };
    const transcriptionFailed = segments.filter(isTranscriptionFailure).length;
    const match = getAutoEditBatchMatchSummary(data);
    // status=error 同时用于两类问题；从中扣除已有明确 ASR 证据的片段，剩下才是文案匹配失败。
    const matchingFailed = Math.max(0, match.error - segments.filter(segment => isTranscriptionFailure(segment) && segment?.status === 'error').length);
    return { transcriptionFailed, matchingFailed, missingScript: match.missingBlocks };
}

function getAutoEditBatchFinalStatus(data) {
    const match = getAutoEditBatchMatchSummary(data);
    const failures = getAutoEditBatchFailureBreakdown(data);
    const total = match.total;
    const recognized = Math.max(0, total - failures.transcriptionFailed);
    const matchReview = match.warning + failures.matchingFailed;
    return {
        recognition: `语音识别：${recognized}/${total} 成功${failures.transcriptionFailed ? ` · ${failures.transcriptionFailed} 失败/空结果` : ''}`,
        matching: `片段匹配：${match.ready}/${total} 通过${matchReview ? ` · ${matchReview} 个待审核` : ''}`,
        coverage: `文案覆盖：${failures.missingScript ? `缺 ${failures.missingScript} 段（未被任何片段匹配）` : '完整'}`,
    };
}

async function copyAutoEditMissingText(text) {
    try {
        if (window.electronAPI?.writeClipboardText) await window.electronAPI.writeClipboardText(text);
        else await navigator.clipboard.writeText(text);
        showToast('已复制', 'success');
    } catch (error) { showToast(`复制失败：${error.message}`, 'error'); }
}

async function copyAutoEditReviewText(button, selector) {
    const row = button?.closest?.('.autoedit-review-row, .autoedit-missing-placeholder');
    const source = selector ? row?.querySelector(selector) : row;
    const text = String(source instanceof HTMLTextAreaElement || source instanceof HTMLInputElement
        ? source.value
        : (source?.innerText || source?.textContent || '')).trim();
    if (!text) return showToast('没有可复制的文字', 'info');
    await copyAutoEditMissingText(text);
}
window.copyAutoEditReviewText = copyAutoEditReviewText;

function buildAutoEditBatchIssuesTable(tasks = []) {
    const list = Array.isArray(tasks) ? tasks : [];
    const rows = [];

    list.forEach(task => {
        const videoName = String(task?.outputName || task?.name || '').trim();
        if (!videoName) return;

        const issueTexts = [];
        // 1. 待确认/缺失文案（优先）
        const missingBlocks = Array.isArray(task?.result?.missing_blocks) ? task.result.missing_blocks : [];
        missingBlocks.forEach(b => {
            if (!b.review_assignment && (b.text || '').trim()) {
                issueTexts.push(b.text.trim());
            }
        });

        // 2. 异常片段文案（如果无 missing_blocks 但有警告/错误片段）
        if (issueTexts.length === 0) {
            const segments = Array.isArray(task?.reviewSegments || task?.result?.review_segments || task?.result?.segments)
                ? (task.reviewSegments || task.result.review_segments || task.result.segments)
                : [];
            segments.forEach(s => {
                if (s?.review_acknowledged !== true && (s?.status === 'warning' || s?.status === 'error')) {
                    const t = (s.text || s.script_text || s.expected_text || '').trim();
                    if (t) issueTexts.push(t);
                }
            });
        }

        // 3. 错误信息兜底
        if (issueTexts.length === 0 && (task?.reelsTransferError || task?.message)) {
            const msg = String(task.reelsTransferError || task.message).trim();
            if (msg && msg !== '待分析' && msg !== '分析完成' && msg !== '匹配通过') {
                issueTexts.push(msg);
            }
        }

        if (issueTexts.length === 0) return;

        // 第一列视频名字固定加：换行 + 需修改（单元格内两行）
        const videoCellContent = `${videoName}\n需修改`;
        const escapedVideoCell = `"${videoCellContent.replace(/"/g, '""')}"`;

        // 格式化问题文案：每个文案用英文双引号引起来；若有多段用换行连接
        const quotedParts = issueTexts.map(t => {
            const clean = t.replace(/^"+|"+$/g, '').trim();
            return `"${clean}"`;
        });
        const cellContent = quotedParts.join('\n');

        // 按照 Google Sheets TSV 规范进行单元格转义：外层包引号，内部引号转为 ""
        const escapedCell = `"${cellContent.replace(/"/g, '""')}"`;
        rows.push({
            videoName,
            videoCellContent,
            cellContent,
            tsvLine: `${escapedVideoCell}\t${escapedCell}`
        });
    });

    const escapeHtmlSimple = str => String(str || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    const escapeHtmlWithBreaks = str => escapeHtmlSimple(str).replace(/\r?\n/g, '<br>');
    const htmlRows = rows.map(r => `<tr><td style="white-space:pre-wrap;mso-data-placement:same-cell;">${escapeHtmlWithBreaks(r.videoCellContent)}</td><td style="white-space:pre-wrap;mso-data-placement:same-cell;">${escapeHtmlWithBreaks(r.cellContent)}</td></tr>`).join('');

    return {
        rows,
        tsvText: rows.map(r => r.tsvLine).join('\n'),
        htmlText: rows.length ? `<meta charset="utf-8"><table>${htmlRows}</table>` : ''
    };
}

async function copyAutoEditBatchIssuesTable(filterMode = 'all', triggerBtn = null) {
    if (!autoEditBatchTasks.length) return showToast('当前没有批量任务', 'info');

    const btn = triggerBtn || (typeof event !== 'undefined' ? event?.currentTarget : null);

    let targetTasks = autoEditBatchTasks.filter(task => {
        if (filterMode === 'issues') return autoEditBatchTaskHasIssues(task);
        if (filterMode === 'selected') return task.sendToReels !== false && autoEditBatchTaskHasIssues(task);
        if (filterMode === 'passed') return false;
        return autoEditBatchTaskHasIssues(task);
    });

    if (!targetTasks.length) {
        targetTasks = autoEditBatchTasks.filter(task => autoEditBatchTaskHasIssues(task));
    }

    if (!targetTasks.length) {
        return showToast('太棒了！当前没有发现未通过或有问题的任务', 'info');
    }

    const { rows, tsvText, htmlText } = buildAutoEditBatchIssuesTable(targetTasks);

    if (!rows.length) {
        return showToast('未提取到有效的问题文案', 'warning');
    }

    try {
        let copied = false;
        if (navigator.clipboard?.write && typeof ClipboardItem !== 'undefined' && htmlText) {
            try {
                await navigator.clipboard.write([
                    new ClipboardItem({
                        'text/plain': new Blob([tsvText], { type: 'text/plain' }),
                        'text/html': new Blob([htmlText], { type: 'text/html' })
                    })
                ]);
                copied = true;
            } catch (_) {}
        }
        if (!copied) {
            if (window.electronAPI?.writeClipboardText) {
                await window.electronAPI.writeClipboardText(tsvText);
            } else if (navigator.clipboard?.writeText) {
                await navigator.clipboard.writeText(tsvText);
            }
        }

        // 按钮点击后的即时视觉反馈
        if (btn && btn.textContent) {
            const origText = btn.textContent;
            const origBg = btn.style.background;
            const origColor = btn.style.color;
            const origBorder = btn.style.borderColor;

            btn.textContent = `✅ 已复制 (${rows.length}个视频)`;
            btn.style.background = 'rgba(34, 197, 94, 0.25)';
            btn.style.color = '#86efac';
            btn.style.borderColor = 'rgba(34, 197, 94, 0.6)';

            setTimeout(() => {
                btn.textContent = origText;
                btn.style.background = origBg;
                btn.style.color = origColor;
                btn.style.borderColor = origBorder;
            }, 2200);
        }

        showToast(`✅ 已复制 ${rows.length} 个问题视频及文案，可直接粘贴到 Google 表格`, 'success');
    } catch (error) {
        showToast(`复制失败：${error.message}`, 'error');
    }
}

function showAutoEditBatchSimpleReport(initialFilter) {
    if (!autoEditBatchTasks.length) return showToast('当前没有批量任务', 'info');
    document.getElementById('autoedit-simple-report')?.remove();
    const overlay = document.createElement('div'); overlay.id = 'autoedit-simple-report';
    overlay.style.cssText = 'position:fixed;inset:0;z-index:100050;background:rgba(0,0,0,0.78);display:grid;place-items:center;padding:20px;';
    const panel = document.createElement('section');
    panel.style.cssText = 'background:#171923;color:#eee;padding:20px;border-radius:12px;width:min(960px,95vw);max-height:88vh;overflow-y:auto;display:flex;flex-direction:column;box-shadow:0 20px 25px -5px rgba(0,0,0,0.5);';
    
    // Header (sticky on top)
    const header = document.createElement('div');
    header.style.cssText = 'position:sticky;top:-20px;margin:-20px -20px 14px -20px;padding:16px 20px;background:#171923;border-bottom:1px solid rgba(255,255,255,0.12);display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;z-index:10;';

    const leftActions = document.createElement('div');
    leftActions.style.cssText = 'display:flex;gap:8px;align-items:center;flex-wrap:wrap;';
    const close = document.createElement('button'); close.className = 'btn btn-secondary'; close.textContent = '关闭'; close.onclick = () => overlay.remove();
    const copy = document.createElement('button'); copy.className = 'btn btn-primary'; copy.textContent = '复制报告';
    const copyIssuesTableBtn = document.createElement('button');
    copyIssuesTableBtn.className = 'btn btn-secondary';
    copyIssuesTableBtn.style.cssText = 'background:rgba(245,158,11,0.18);color:#fde047;border:1px solid rgba(245,158,11,0.45);font-weight:600;transition:all .2s ease;';
    copyIssuesTableBtn.textContent = '📋 复制问题文案(表格)';
    copyIssuesTableBtn.title = '复制两列：第一列问题视频名，第二列双引号问题文案（整段在一个单元格内），可直接贴到 Google 表格';
    copyIssuesTableBtn.onclick = (e) => copyAutoEditBatchIssuesTable(currentFilter, copyIssuesTableBtn);
    leftActions.append(close, copy, copyIssuesTableBtn);

    // Filter controls
    let currentFilter = initialFilter || (autoEditBatchTaskFilter === 'selected' || autoEditBatchTaskFilter === 'issues' || autoEditBatchTaskFilter === 'passed' ? autoEditBatchTaskFilter : 'all');

    const filterGroup = document.createElement('div');
    filterGroup.style.cssText = 'display:flex;gap:6px;align-items:center;flex-wrap:wrap;';
    const filterLabel = document.createElement('span');
    filterLabel.style.cssText = 'font-size:12px;color:var(--text-secondary,#94a3b8);';
    filterLabel.textContent = '筛选报告：';
    filterGroup.append(filterLabel);

    const filterBtns = {
        all: document.createElement('button'),
        passed: document.createElement('button'),
        issues: document.createElement('button'),
        selected: document.createElement('button'),
    };
    filterGroup.append(filterBtns.all, filterBtns.passed, filterBtns.issues, filterBtns.selected);
    header.append(leftActions, filterGroup);

    const body = document.createElement('div');
    body.style.cssText = 'display:flex;flex-direction:column;gap:12px;';

    const renderReportList = () => {
        body.replaceChildren();
        const issuesCount = autoEditBatchTasks.filter(t => autoEditBatchTaskHasIssues(t)).length;
        const passedCount = autoEditBatchTasks.filter(t => Boolean(t?.clips?.length) && !autoEditBatchTaskHasIssues(t)).length;
        const selectedCount = autoEditBatchTasks.filter(t => t.sendToReels !== false).length;
        const allCount = autoEditBatchTasks.length;

        filterBtns.all.textContent = `全部 (${allCount})`;
        filterBtns.all.className = `btn ${currentFilter === 'all' ? 'btn-primary' : 'btn-secondary'}`;
        filterBtns.passed.textContent = `通过 (${passedCount})`;
        filterBtns.passed.className = `btn ${currentFilter === 'passed' ? 'btn-primary' : 'btn-secondary'}`;
        filterBtns.issues.textContent = `未通过 (${issuesCount})`;
        filterBtns.issues.className = `btn ${currentFilter === 'issues' ? 'btn-primary' : 'btn-secondary'}`;
        filterBtns.selected.textContent = `仅选择的 (${selectedCount})`;
        filterBtns.selected.className = `btn ${currentFilter === 'selected' ? 'btn-primary' : 'btn-secondary'}`;

        const filteredTasks = autoEditBatchTasks.filter(task => {
            if (currentFilter === 'issues') return autoEditBatchTaskHasIssues(task);
            if (currentFilter === 'passed') return Boolean(task?.clips?.length) && !autoEditBatchTaskHasIssues(task);
            if (currentFilter === 'selected') return task.sendToReels !== false;
            return true;
        });

        if (!filteredTasks.length) {
            const empty = document.createElement('div');
            empty.style.cssText = 'text-align:center;padding:48px 20px;color:#94a3b8;font-size:13px;';
            empty.textContent = currentFilter === 'issues' ? '太棒了！没有发现未通过的任务' : (currentFilter === 'passed' ? '当前没有通过的任务' : (currentFilter === 'selected' ? '当前没有已勾选选中的任务' : '暂无任务报告'));
            body.append(empty);
            return;
        }

        filteredTasks.forEach(task => {
            const section = document.createElement('section');
            section.style.cssText = 'margin:4px 0;padding:14px;border:1px solid #475569;border-radius:8px;background:rgba(255,255,255,0.02);';
            const title = document.createElement('h3');
            title.style.cssText = 'margin:0 0 8px 0;font-size:15px;display:flex;align-items:center;gap:8px;';
            title.textContent = task.outputName || task.name;
            section.append(title);
            // 复用审核列表的原位排序，报告中的缺失卡与片段保持同一顺序。
            section.insertAdjacentHTML('beforeend', renderAutoEditBatchMatchResult(task) || `<p>${escapeHtml(task.message || '待分析')}</p>`);
            section.querySelectorAll('details').forEach(el => el.open = true);
            section.querySelectorAll('[style*="max-height"]').forEach(el => { el.style.maxHeight = 'none'; });
            body.append(section);
        });
    };

    filterBtns.all.onclick = () => { currentFilter = 'all'; renderReportList(); };
    filterBtns.passed.onclick = () => { currentFilter = 'passed'; renderReportList(); };
    filterBtns.issues.onclick = () => { currentFilter = 'issues'; renderReportList(); };
    filterBtns.selected.onclick = () => { currentFilter = 'selected'; renderReportList(); };

    copy.onclick = () => copyAutoEditMissingText(body.innerText);

    panel.append(header, body);
    overlay.append(panel);
    document.body.append(overlay);
    renderReportList();
}

async function archiveAutoEditBatchSelectedTasks() {
    if (autoEditBatchRunning || autoEditActiveRequestIds.size) return showToast('请在当前任务完成后整理', 'info');
    const tasks = autoEditBatchTasks.filter(task => task.clips?.length && task.sendToReels !== false);
    if (!tasks.length) return showToast('当前没有选中的任务，请先勾选需要整理的任务卡片（参与本次导出）', 'warning');

    document.getElementById('autoedit-archive-modal')?.remove();

    let selectedDestPath = '';
    let selectedMode = 'copy';

    const overlay = document.createElement('div');
    overlay.id = 'autoedit-archive-modal';
    overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.78);z-index:100060;display:grid;place-items:center;padding:20px;';

    const modal = document.createElement('div');
    modal.style.cssText = 'background:#171923;border:1px solid rgba(255,255,255,0.18);border-radius:12px;width:min(540px,95vw);padding:24px;color:#eee;box-shadow:0 25px 50px -12px rgba(0,0,0,0.7);display:flex;flex-direction:column;gap:16px;';

    const renderConfigView = () => {
        modal.innerHTML = `
            <div style="display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid rgba(255,255,255,0.1);padding-bottom:12px;">
                <h3 style="margin:0;font-size:16px;font-weight:700;display:flex;align-items:center;gap:8px;">📦 整理选中的任务文件夹</h3>
                <span style="font-size:12px;padding:3px 8px;border-radius:12px;background:rgba(99,102,241,0.2);color:#c7d2fe;">已勾选 ${tasks.length} 个任务</span>
            </div>

            <div>
                <label style="font-size:12px;font-weight:600;color:#c7d2fe;display:block;margin-bottom:8px;">整理方式选择：</label>
                <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;">
                    <label id="archive-mode-copy-card" style="display:flex;flex-direction:column;gap:4px;padding:12px;border:1px solid ${selectedMode === 'copy' ? '#6366f1' : 'rgba(255,255,255,0.12)'};border-radius:8px;background:${selectedMode === 'copy' ? 'rgba(99,102,241,0.14)' : 'rgba(255,255,255,0.03)'};cursor:pointer;transition:.15s;">
                        <div style="display:flex;align-items:center;gap:6px;font-weight:600;font-size:13px;color:#fff;">
                            <input type="radio" name="ae-archive-mode" value="copy" ${selectedMode === 'copy' ? 'checked' : ''} style="margin:0;">
                            📋 复制到总文件夹
                        </div>
                        <span style="font-size:11px;color:#94a3b8;line-height:1.4;">原文件夹保留在原地不变（更安全）</span>
                    </label>
                    <label id="archive-mode-move-card" style="display:flex;flex-direction:column;gap:4px;padding:12px;border:1px solid ${selectedMode === 'move' ? '#ef4444' : 'rgba(255,255,255,0.12)'};border-radius:8px;background:${selectedMode === 'move' ? 'rgba(239,68,68,0.14)' : 'rgba(255,255,255,0.03)'};cursor:pointer;transition:.15s;">
                        <div style="display:flex;align-items:center;gap:6px;font-weight:600;font-size:13px;color:#fca5a5;">
                            <input type="radio" name="ae-archive-mode" value="move" ${selectedMode === 'move' ? 'checked' : ''} style="margin:0;">
                            ✂️ 移动到总文件夹
                        </div>
                        <span style="font-size:11px;color:#94a3b8;line-height:1.4;">剪切移动到总文件夹，原目录不再保留</span>
                    </label>
                </div>
            </div>

            <div>
                <label style="font-size:12px;font-weight:600;color:#c7d2fe;display:block;margin-bottom:6px;">目标总文件夹：</label>
                <div style="display:flex;gap:8px;">
                    <input id="autoedit-archive-dest-input" class="input" readonly value="${escapeHtml(selectedDestPath)}" placeholder="请点击右侧按钮选择目标总文件夹..." style="flex:1;font-size:12px;background:rgba(0,0,0,0.25);">
                    <button id="autoedit-archive-browse-btn" class="btn btn-secondary" style="white-space:nowrap;">📁 选择文件夹</button>
                </div>
            </div>

            <div style="display:flex;justify-content:flex-end;gap:10px;margin-top:8px;padding-top:14px;border-top:1px solid rgba(255,255,255,0.1);">
                <button id="autoedit-archive-cancel-btn" class="btn btn-secondary">取消</button>
                <button id="autoedit-archive-start-btn" class="btn btn-primary" ${!selectedDestPath ? 'disabled' : ''}>开始整理</button>
            </div>
        `;

        modal.querySelectorAll('input[name="ae-archive-mode"]').forEach(radio => {
            radio.onchange = (e) => {
                selectedMode = e.target.value;
                renderConfigView();
            };
        });

        modal.querySelector('#autoedit-archive-cancel-btn').onclick = () => overlay.remove();

        modal.querySelector('#autoedit-archive-browse-btn').onclick = async () => {
            const folder = await window.electronAPI.selectDirectory({ title: '选择用于存放整理文件夹的目标总文件夹' });
            if (folder) {
                selectedDestPath = folder;
                renderConfigView();
            }
        };

        const startBtn = modal.querySelector('#autoedit-archive-start-btn');
        if (startBtn) {
            startBtn.onclick = () => startArchiving();
        }
    };

    const startArchiving = async () => {
        if (!selectedDestPath) return showToast('请先选择目标总文件夹', 'warning');
        setAutoEditBatchRunning(true);

        modal.innerHTML = `
            <div style="border-bottom:1px solid rgba(255,255,255,0.1);padding-bottom:12px;">
                <h3 style="margin:0;font-size:16px;font-weight:700;">⏳ 正在整理任务文件夹...</h3>
            </div>
            <div style="display:flex;flex-direction:column;gap:10px;margin:8px 0;">
                <div style="display:flex;justify-content:space-between;align-items:center;font-size:13px;">
                    <span id="ae-archive-current-task" style="color:#e2e8f0;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:360px;">准备开始...</span>
                    <span id="ae-archive-percent" style="color:#818cf8;font-weight:700;">0%</span>
                </div>
                <div style="height:12px;background:rgba(255,255,255,0.1);border-radius:6px;overflow:hidden;position:relative;">
                    <div id="ae-archive-progress-bar" style="height:100%;width:0%;background:linear-gradient(90deg,#6366f1,#a855f7);transition:width 0.25s ease;"></div>
                </div>
                <div id="ae-archive-count-info" style="font-size:11px;color:#94a3b8;display:flex;justify-content:space-between;">
                    <span>模式：${selectedMode === 'move' ? '✂️ 移动剪切' : '📋 复制备份'}</span>
                    <span id="ae-archive-ratio">0 / ${tasks.length}</span>
                </div>
            </div>
        `;

        let unsubscribe = null;
        if (window.electronAPI?.onAutoEditArchiveProgress) {
            unsubscribe = window.electronAPI.onAutoEditArchiveProgress(data => {
                const bar = modal.querySelector('#ae-archive-progress-bar');
                const percent = modal.querySelector('#ae-archive-percent');
                const taskLabel = modal.querySelector('#ae-archive-current-task');
                const ratio = modal.querySelector('#ae-archive-ratio');
                if (bar) bar.style.width = (data.percent || 0) + '%';
                if (percent) percent.textContent = (data.percent || 0) + '%';
                if (taskLabel) taskLabel.textContent = `${data.mode === 'move' ? '正在移动' : '正在复制'}：${data.taskName || ''}`;
                if (ratio) ratio.textContent = `${data.current || 0} / ${data.total || tasks.length}`;
            });
        }

        try {
            const response = await window.electronAPI.apiCall('media/archive-autoedit-selected-tasks', {
                destinationRoot: selectedDestPath,
                mode: selectedMode,
                tasks: tasks.map(task => ({
                    ...task,
                    match_summary: getAutoEditBatchTaskSummary(task),
                    missing_blocks: task.result?.missing_blocks || []
                }))
            });

            if (unsubscribe) unsubscribe();

            if (!response.success) throw new Error(response.error);
            const { archived, failed, destinationRoot, mode } = response.data;

            if (mode === 'move' && Array.isArray(archived)) {
                const norm = p => String(p || '').replace(/\\/g, '/').replace(/\/+$/, '');
                archived.forEach(item => {
                    const task = autoEditBatchTasks.find(t => norm(t.folder) === norm(item.sourceFolder));
                    if (task) {
                        task.folder = item.destinationFolder;
                        if (Array.isArray(task.clips)) {
                            task.clips = task.clips.map(c => c.replace(item.sourceFolder, item.destinationFolder));
                        }
                    }
                });
                saveAutoEditWorkspaceState();
                renderAutoEditBatchTasks();
            }

            modal.innerHTML = `
                <div style="text-align:center;padding:10px 0;">
                    <div style="font-size:36px;margin-bottom:8px;">✅</div>
                    <h3 style="margin:0 0 8px 0;font-size:17px;color:#fff;">整理完成！</h3>
                    <p style="margin:0 0 16px 0;font-size:13px;color:#94a3b8;">
                        已成功${mode === 'move' ? '移动' : '复制'} <strong>${archived.length}</strong> 个任务文件夹到总目录${failed.length ? `，失败 ${failed.length} 个` : ''}。
                    </p>
                    <div style="display:flex;justify-content:center;gap:12px;">
                        <button id="ae-archive-open-dest-btn" class="btn btn-primary">📁 打开总文件夹</button>
                        <button id="ae-archive-done-btn" class="btn btn-secondary">完成</button>
                    </div>
                </div>
            `;

            modal.querySelector('#ae-archive-open-dest-btn').onclick = () => {
                if (window.electronAPI?.showItemInFolder) {
                    window.electronAPI.showItemInFolder(destinationRoot);
                }
            };
            modal.querySelector('#ae-archive-done-btn').onclick = () => overlay.remove();

        } catch (error) {
            if (unsubscribe) unsubscribe();
            modal.innerHTML = `
                <div style="text-align:center;padding:10px 0;">
                    <div style="font-size:36px;margin-bottom:8px;">❌</div>
                    <h3 style="margin:0 0 8px 0;font-size:17px;color:#f87171;">整理失败</h3>
                    <p style="margin:0 0 16px 0;font-size:13px;color:#fca5a5;">${escapeHtml(error.message)}</p>
                    <button id="ae-archive-fail-close-btn" class="btn btn-secondary">关闭</button>
                </div>
            `;
            modal.querySelector('#ae-archive-fail-close-btn').onclick = () => overlay.remove();
        } finally {
            setAutoEditBatchRunning(false);
        }
    };

    overlay.append(modal);
    document.body.append(overlay);
    renderConfigView();
}
async function archiveAutoEditBatchFailedTasks() {
    return archiveAutoEditBatchSelectedTasks();
}

async function refreshAutoEditBatchTaskFolder(index) {
    const task = autoEditBatchTasks[index];
    if (!task?.folder || autoEditBatchRunning || autoEditActiveRequestIds.size) return showToast('请在当前任务完成后刷新', 'info');
    setAutoEditBatchRunning(true);
    try {
        const entries = await scanAutoEditBatchFolderRecursive(task.folder);
        const clips = filterAutoEditSourceVideos(entries, /\.(mp4|mov|mkv|avi|wmv|flv|webm|m4v)$/i).map(entry => entry.path);
        if (!clips.length) return showToast('没有找到原始视频，已排除工程输出', 'warning');
        task.clips = clips; task.exportSignature = '';
        if (!task.script?.trim()) return showToast('素材已刷新，请填写文案后分析', 'info');
        await analyzeAutoEditBatchTask(task);
        saveAutoEditWorkspaceState();
    } catch (error) { showToast(`刷新失败：${error.message}`, 'error'); }
    finally { setAutoEditBatchRunning(false); }
}

async function refreshAutoEditBatchSelectedTaskFolders() {
    if (autoEditBatchRunning || autoEditActiveRequestIds.size) return showToast('请等待当前任务完成后再刷新', 'info');
    const selected = autoEditBatchTasks.filter(task => task?.folder && task.sendToReels !== false);
    if (!selected.length) return showToast('请先勾选需要刷新的任务', 'info');
    const videoExt = /\.(mp4|mov|mkv|avi|wmv|flv|webm|m4v)$/i;
    let refreshed = 0;
    let failed = 0;
    setAutoEditBatchRunning(true);
    try {
        // 逐套刷新能复用既有的人工审核快照，且不会把多份重转录同时压到服务上。
        for (const task of selected) {
            task.message = '正在刷新文件夹…';
            renderAutoEditBatchTasks();
            try {
                const entries = await scanAutoEditBatchFolderRecursive(task.folder);
                const clips = filterAutoEditSourceVideos(entries, videoExt).map(entry => entry.path);
                if (!clips.length) throw new Error('没有找到原始视频（工程输出已自动排除）');
                task.clips = clips;
                task.exportSignature = '';
                if (!task.script?.trim()) {
                    task.status = 'skipped';
                    task.message = '素材已刷新，但缺少文案，未分析';
                    continue;
                }
                await analyzeAutoEditBatchTask(task);
                refreshed++;
            } catch (error) {
                failed++;
                task.status = 'error';
                task.message = `刷新失败：${error.message || error}`;
            }
        }
        saveAutoEditWorkspaceState();
        showToast(`已刷新并分析 ${refreshed}/${selected.length} 个选中任务${failed ? `，${failed} 个失败` : ''}`, failed ? 'warning' : 'success', 7000);
    } finally {
        setAutoEditBatchRunning(false);
        renderAutoEditBatchTasks();
    }
}
window.showAutoEditBatchSimpleReport = showAutoEditBatchSimpleReport;
window.copyAutoEditBatchIssuesTable = copyAutoEditBatchIssuesTable;
window.buildAutoEditBatchIssuesTable = buildAutoEditBatchIssuesTable;
