window.archiveAutoEditBatchFailedTasks = archiveAutoEditBatchSelectedTasks;
window.refreshAutoEditBatchTaskFolder = refreshAutoEditBatchTaskFolder;
window.selectAllAutoEditBatchTasks = selectAllAutoEditBatchTasks;
window.deselectAllAutoEditBatchTasks = deselectAllAutoEditBatchTasks;
window.selectAutoEditBatchPassedTasks = selectAutoEditBatchPassedTasks;
window.selectAutoEditBatchFailedTasks = selectAutoEditBatchFailedTasks;
window.selectAutoEditBatchUnexportedTasks = selectAutoEditBatchUnexportedTasks;
window.refreshAutoEditBatchSelectedTaskFolders = refreshAutoEditBatchSelectedTaskFolders;

function restoreAutoEditMissingBlockAssignments(data, previous, aliases = []) {
    const normalize = value => String(value || '').replace(/\\/g, '/');
    const oldSegments = previous?.segments || [];
    let restoredCount = 0;
    for (const block of data.missing_blocks || []) {
        const oldCandidates = (previous?.missing_blocks || []).filter(item => item.review_assignment
            && normalizeAutoEditReviewText(item.text) === normalizeAutoEditReviewText(block.text));
        // 文案本身相同才可恢复；优先保持原行号。重分析可能因断行或边界校正
        // 改变行号，此时只有唯一同文案的旧处理记录才允许沿用，避免错贴状态。
        const old = oldCandidates.find(item => item.startLine === block.startLine && item.endLine === block.endLine)
            || (oldCandidates.length === 1 ? oldCandidates[0] : null);
        if (!old) continue;
        const targets = (old.review_assignment.targets || []).map(target => {
            let source = normalize(target.source || oldSegments.find(segment => Number(segment.source_index || segment.index) === Number(target.source_index))?.source);
            if (aliases.length >= 2 && source === normalize(aliases[0])) source = normalize(aliases[1]);
            const segment = (data.segments || []).find(item => normalize(item.source) === source);
            return segment ? { ...target, source: segment.source, source_index: segment.source_index || segment.index } : null;
        });
        if (targets.length && targets.every(Boolean)) {
            block.review_assignment = { ...old.review_assignment, targets };
            restoredCount++;
        }
    }
    return restoredCount;
}
function hasAutoEditHumanReview(segment) {
    return Boolean(segment && (segment.manually_modified || segment.review_acknowledged || segment.is_hook
        || segment.enabled === false || segment.needs_replacement === true || segment.missing_confirmed_for
        || segment.visual_remove_ranges?.length || segment.manual_subtitles?.length));
}

function renderAutoEditBatchMatchResult(task) {
    if (!task?.result) return '<div class="hint">尚未分析，没有审核结果</div>';
    task = { ...task, result: { ...task.result, segments: task.reviewSegments || task.result.review_segments || task.result.segments || [] } };
    const isMultilingualV2 = ['multilingual_v2', 'compare_v2'].includes(task.result.matching_engine);
    const engineLabel = task.result.matching_engine === 'compare_v2' ? '经典/V2 对比' : (isMultilingualV2 ? '智能版 V2' : '经典版');
    const segments = Array.isArray(task.result.segments) ? task.result.segments : [];
    const summary = getAutoEditBatchMatchSummary(task.result);
    const hasIssues = summary.error > 0 || summary.warning > 0 || summary.missingBlocks > 0;
    const orderedSegments = segments.slice().sort((a, b) => Number(a.source_index || a.index) - Number(b.source_index || b.index));
    const missingBlocks = Array.isArray(task.result.missing_blocks) ? task.result.missing_blocks : [];
    const duplicateSegments = orderedSegments.filter(segment => Number(segment?.duplicate_of_source_index) > 0 && segment?.review_acknowledged !== true);
    const ordinaryWarnings = orderedSegments.filter(segment => segment?.review_acknowledged !== true && segment?.status === 'warning' && !(Number(segment?.duplicate_of_source_index) > 0));
    const missingPlacement = missingBlocks.map((block, index) => {
        const startLine = Number(block.startLine) + 1;
        const endLine = Number(block.endLine) + 1;
        const previous = Number(block.previous_source_index) || Number(orderedSegments
            .filter(segment => Number(segment.script_end_line || 0) > 0 && Number(segment.script_end_line || 0) < startLine)
            .sort((a, b) => Number(b.script_end_line || 0) - Number(a.script_end_line || 0))[0]?.source_index) || null;
        const next = Number(block.next_source_index) || Number(orderedSegments
            .filter(segment => Number(segment.script_start_line || Infinity) > endLine)
            .sort((a, b) => Number(a.script_start_line || Infinity) - Number(b.script_start_line || Infinity))[0]?.source_index) || null;
        return { block, index, startLine, endLine, previous, next };
    });
    const renderMissingRow = item => {
        const { block, index, startLine, endLine, previous, next } = item;
        const segmentName = sourceIndex => {
            const segment = orderedSegments.find(entry => Number(entry?.source_index || entry?.index) === Number(sourceIndex));
            return String(segment?.source || '').split(/[/\\]/).pop() || `片段 #${sourceIndex}`;
        };
        const previousLabel = previous ? `#${previous}「${segmentName(previous)}」` : '';
        const nextLabel = next ? `#${next}「${segmentName(next)}」` : '';
        const label = previous && next ? `位于片段 ${previousLabel} 与 ${nextLabel} 之间` : (previous ? `位于片段 ${previousLabel} 后` : (next ? `位于片段 ${nextLabel} 前` : '位置待确认'));
        const confirmedMissing = block.issue_type === 'confirmed_missing_script' || block.detection_method;
        const issueLabel = block.review_assignment ? '✓ 已归属（审核页可撤销）'
            : (confirmedMissing ? '❌ 确认缺失文案' : '⚠️ 归属待确认文案');
        const explanation = block.review_assignment ? ''
            : (confirmedMissing
                ? '已核对所有素材识别全文及相邻片段边界，仍未被任何片段覆盖。'
                : (block.issue_reason || '存在多个可能归属或识别证据不足，请试听相邻片段。'));
        const border = block.review_assignment ? '#51cf66' : (confirmedMissing ? '#ff6b6b' : '#fbbf24');
        const background = block.review_assignment ? 'rgba(81,207,102,.08)' : (confirmedMissing ? 'rgba(255,107,107,.08)' : 'rgba(251,191,36,.08)');
        const color = block.review_assignment ? '#86efac' : (confirmedMissing ? '#fca5a5' : '#fcd34d');
        return `<div class="ae-batch-match-row" data-batch-match-state="${block.review_assignment ? 'handled' : 'failed'}" style="grid-column:1/-1;margin:3px 0;padding:6px 8px;border-left:3px solid ${border};border-radius:4px;background:${background};font-size:11px;color:${color};"><strong>${issueLabel} #${index + 1}</strong> · ${escapeHtml(label)} · 第 ${startLine}${endLine > startLine ? `–${endLine}` : ''} 行<br><span style="display:block;margin-top:2px;color:${color};opacity:.9;">${escapeHtml(explanation)}</span><span style="display:block;margin-top:3px;white-space:pre-wrap;word-break:break-word;">${escapeHtml(block.text || '')}</span></div>`;
    };
    const renderMissingWithCopy = item => `<div>${renderMissingRow(item)}<button class="btn btn-secondary" data-copy="${escapeHtml(encodeURIComponent('"' + (item.block.text || '') + '"'))}" onclick="copyAutoEditMissingText(decodeURIComponent(this.dataset.copy))">复制当前文案</button></div>`;
    const renderedMissing = new Set();
    const rows = orderedSegments.flatMap((segment, index) => {
        const sourceIndex = Number(segment.source_index || segment.index) || index + 1;
        const before = missingPlacement.filter(item => !item.previous && item.next === sourceIndex);
        const after = missingPlacement.filter(item => item.previous === sourceIndex);
        [...before, ...after].forEach(item => renderedMissing.add(item.index));
        const status = segment?.status || 'warning';
        const handled = segment.review_acknowledged === true;
        const matchState = handled ? 'handled' : (status === 'ready' ? 'passed' : 'failed');
        const icon = handled ? '✓' : (status === 'ready' ? '✅' : (status === 'error' ? '❌' : '⚠️'));
        const color = handled ? '#86efac' : (status === 'ready' ? '#51cf66' : (status === 'error' ? '#ff6b6b' : '#ff9f43'));
        const fileName = String(segment?.source || '').split(/[/\\]/).pop() || `片段 #${index + 1}`;
        const similarity = Number.isFinite(Number(segment?.similarity)) ? `${Number(segment.similarity)}%` : '未知';
        const duplicateOf = Number(segment?.duplicate_of_source_index) || null;
        const reason = duplicateOf
            ? `重复朗读：与片段 #${duplicateOf} 内容重复，已复用相同文案位置`
            : (segment?.issue_reason || segment?.ambiguity || (status === 'ready' ? '匹配通过' : '需人工审核'));
        // 文件名是人工复核时最重要的信息；通过状态不再重复占一列，
        // 让长文件名完整换行显示，异常原因仍可在右侧看到。
        const compactStatus = handled ? '已处理（审核页可撤销）' : duplicateOf
            ? `🔁 重复片段 · 原片段 #${duplicateOf}`
            : status === 'ready'
            ? `✓ ${escapeHtml(similarity)}`
            : `${icon} ${escapeHtml(similarity)} · ${escapeHtml(reason)}`;
        const encodedSource = encodeURIComponent(segment?.source || '');
        const thumbnailHtml = segment?.source
            ? `<button class="ae-batch-review-thumb" data-autoedit-thumb-source="${escapeHtml(encodedSource)}" onclick="playAutoEditBatchReviewThumbnail(this)" title="点击预览原始素材"><span>加载中</span></button>`
            : '<span class="ae-batch-review-thumb ae-batch-review-thumb-empty">无素材</span>';
        return [...before.map(renderMissingWithCopy), `<div class="ae-batch-match-row" data-batch-match-state="${matchState}" style="padding:5px 0;border-bottom:1px solid rgba(255,255,255,.07);display:grid;grid-template-columns:66px minmax(0,1fr) auto;gap:10px;align-items:center;font-size:11px;">
            ${thumbnailHtml}
            <span title="${escapeHtml(segment?.source || fileName)}" style="overflow-wrap:anywhere;word-break:break-word;color:${color};">${icon} #${segment?.source_index || index + 1} ${escapeHtml(fileName)}</span>
            <span title="${escapeHtml(reason)}" style="color:${status === 'ready' ? '#51cf66' : color};white-space:nowrap;">${compactStatus}</span>
        </div>`, ...after.map(renderMissingWithCopy)];
    }).join('') + missingPlacement.filter(item => !renderedMissing.has(item.index)).map(renderMissingWithCopy).join('');
    const failedCount = orderedSegments.filter(segment => segment?.review_acknowledged !== true && segment?.status !== 'ready').length
        + missingBlocks.filter(block => !block.review_assignment).length;
    const handledCount = orderedSegments.filter(segment => segment?.review_acknowledged === true).length
        + missingBlocks.filter(block => block.review_assignment).length;
    return `<details ${hasIssues ? 'open' : ''} style="margin-top:8px;border:1px solid ${hasIssues ? 'rgba(255,159,67,.45)' : 'rgba(81,207,102,.35)'};border-radius:7px;padding:7px;background:rgba(0,0,0,.14);">
        <summary style="cursor:pointer;font-size:12px;color:${hasIssues ? '#ffd8a8' : '#b2f2bb'};">
            ${engineLabel}匹配结果：${summary.ready}/${summary.total} 通过 · ${summary.warning} 警告 · ${summary.error} 失败${summary.missingBlocks ? ` · ${summary.missingBlocks} 段确认缺失文案` : ''}${duplicateSegments.length ? ` · ${duplicateSegments.length} 个重复片段` : ''}${ordinaryWarnings.length ? ` · ${ordinaryWarnings.length} 个识别差异待试听` : ''}${summary.handled ? ` · 已处理 ${summary.handled}（可撤销）` : ''}
        </summary>
        <div class="ae-batch-match-filter" style="display:flex;gap:5px;align-items:center;flex-wrap:wrap;margin-top:7px;">
            <span class="hint">素材筛选：</span>
            <button class="btn btn-secondary" onclick="filterAutoEditBatchMatchRows(this,'all')" style="padding:2px 7px;font-size:10px;">全部</button>
            <button class="btn btn-secondary" onclick="filterAutoEditBatchMatchRows(this,'failed')" style="padding:2px 7px;font-size:10px;">仅不合格 (${failedCount})</button>
            <button class="btn btn-secondary" onclick="filterAutoEditBatchMatchRows(this,'handled')" style="padding:2px 7px;font-size:10px;">修改后合格 (${handledCount})</button>
        </div>
        <div class="ae-batch-match-list" style="margin-top:6px;max-height:240px;overflow:auto;">${rows || '<div class="hint">未返回片段匹配明细</div>'}</div>
    </details>`;
}

function filterAutoEditBatchMatchRows(button, filter) {
    const details = button?.closest('details');
    if (!details) return;
    details.querySelectorAll('.ae-batch-match-row').forEach(row => {
        // 每行本身带有 inline display:grid；仅设置 hidden 在某些窗口样式中会
        // 被这个内联布局重新覆盖，造成“仅不合格”仍显示绿色通过项。
        // 保存原显示方式，筛选时直接控制 display，确保筛选实际生效。
        if (row.dataset.batchMatchDisplay === undefined) row.dataset.batchMatchDisplay = row.style.display || '';
        const visible = filter === 'all' || row.dataset.batchMatchState === filter;
        row.hidden = !visible;
        row.style.display = visible ? row.dataset.batchMatchDisplay : 'none';
    });
    details.querySelectorAll('.ae-batch-match-filter .btn').forEach(item => {
        item.classList.toggle('btn-primary', item === button);
        item.classList.toggle('btn-secondary', item !== button);
    });
}
window.filterAutoEditBatchMatchRows = filterAutoEditBatchMatchRows;

function playAutoEditBatchReviewThumbnail(button) {
    let source = '';
    try { source = decodeURIComponent(button?.dataset?.autoeditThumbSource || ''); } catch (_) {}
    if (source) window.playVideoClip?.(source, 0, 0);
}

function pumpAutoEditReviewThumbnailQueue() {
    while (autoEditReviewThumbnailWorkers < 2 && autoEditReviewThumbnailQueue.length) {
        const source = autoEditReviewThumbnailQueue.shift();
        autoEditReviewThumbnailWorkers++;
        batchCutGenThumb(source).then(thumbnail => {
            autoEditReviewThumbnailCache.set(source, thumbnail || '');
            document.querySelectorAll('.ae-batch-review-thumb[data-autoedit-thumb-source]').forEach(el => {
                let elementSource = '';
                try { elementSource = decodeURIComponent(el.dataset.autoeditThumbSource || ''); } catch (_) {}
                if (elementSource !== source) return;
                el.innerHTML = thumbnail ? `<img src="${thumbnail}" alt="素材缩略图">` : '<span>无预览</span>';
                el.classList.toggle('ae-batch-review-thumb-failed', !thumbnail);
            });
        }).catch(() => {
            autoEditReviewThumbnailCache.set(source, '');
        }).finally(() => {
            autoEditReviewThumbnailWorkers--;
            autoEditReviewThumbnailLoading.delete(source);
            pumpAutoEditReviewThumbnailQueue();
        });
    }
}

function hydrateAutoEditBatchReviewThumbnails(root = document) {
    root.querySelectorAll?.('.ae-batch-review-thumb[data-autoedit-thumb-source]').forEach(el => {
        let source = '';
        try { source = decodeURIComponent(el.dataset.autoeditThumbSource || ''); } catch (_) {}
        if (!source) return;
        if (autoEditReviewThumbnailCache.has(source)) {
            const thumbnail = autoEditReviewThumbnailCache.get(source);
            el.innerHTML = thumbnail ? `<img src="${thumbnail}" alt="素材缩略图">` : '<span>无预览</span>';
            el.classList.toggle('ae-batch-review-thumb-failed', !thumbnail);
            return;
        }
        if (!autoEditReviewThumbnailLoading.has(source)) {
            autoEditReviewThumbnailLoading.add(source);
            autoEditReviewThumbnailQueue.push(source);
        }
    });
    pumpAutoEditReviewThumbnailQueue();
}
window.playAutoEditBatchReviewThumbnail = playAutoEditBatchReviewThumbnail;

function renderAutoEditBatchTasks() {
    const root = document.getElementById('autoedit-batch-task-list'); if (!root) return;
    const summary = document.getElementById('autoedit-batch-summary');
    const scriptCount = autoEditBatchScriptCells.length || autoEditBatchTasks.filter(t => t.script).length;
    if (summary) {
        const analyzed = autoEditBatchTasks.filter(task => task.result?.analysis_only);
        const totals = analyzed.reduce((acc, task) => {
            const item = getAutoEditBatchTaskSummary(task);
            acc.ready += item.ready; acc.warning += item.warning; acc.error += item.error; acc.missing += item.missingBlocks;
            return acc;
        }, { ready: 0, warning: 0, error: 0, missing: 0 });
        const resultText = analyzed.length
            ? ` · 已分析 ${analyzed.length}/${autoEditBatchTasks.length} 套：${totals.ready} 通过、${totals.warning} 警告、${totals.error} 失败${totals.missing ? `、${totals.missing} 段缺失文案` : ''}`
            : '';
        summary.textContent = `${autoEditBatchTasks.length} 个文件夹 · ${scriptCount} 个文案单元格 · ${autoEditBatchTasks.filter(t => t.script).length} 个已配对${resultText}`;
        const running = autoEditBatchTasks.filter(task => ['analyzing', 'exporting'].includes(task.status)).length;
        const exported = autoEditBatchTasks.filter(task => task.status === 'exported').length;
        const progress = document.createElement('strong');
        progress.style.color = '#60a5fa';
        progress.textContent = ` · 进行中 ${running} · 已导出 ${exported}/${autoEditBatchTasks.length}`;
        summary.append(progress);
    }
    syncAutoEditBatchGladiaSettings();
    renderAutoEditBatchGladiaConcurrencyPlan();
    renderAutoEditBatchProgressOverview();
    const matchHint = document.getElementById('autoedit-batch-match-hint');
    if (matchHint) {
        const validScriptCount = autoEditBatchScriptCells.filter(s => String(s || '').trim()).length;
        const extraCount = Math.max(0, validScriptCount - autoEditBatchTasks.length);
        const missingCount = Math.max(0, autoEditBatchTasks.length - validScriptCount);
        const pairedCount = autoEditBatchTasks.filter(t => t.script?.trim()).length;
        matchHint.textContent = !autoEditBatchTasks.length
            ? (scriptCount ? `已识别 ${scriptCount} 个文案单元格（${validScriptCount} 个有效）；请选择文件夹配对。` : '粘贴后自动识别；第 N 个单元格对应第 N 个文件夹。')
            : (autoEditBatchSmartPairingComplete
                ? `✅ ${pairedCount} 个任务已智能配对${missingCount ? ` · ${missingCount} 个空文案任务已自动跳过` : (extraCount ? ` · ${extraCount} 个文案未匹配` : '')}`
                : (extraCount
                    ? `⚠️ 文案比任务多 ${extraCount} 个；点击「智能配对」自动选出最匹配的 ${autoEditBatchTasks.length} 个`
                    : (missingCount ? `💡 检测到 ${validScriptCount} 个有效文案（缺少 ${missingCount} 个）；点击「智能配对」自动匹配最吻合的组合，其余自动跳过` : `✅ ${scriptCount} 个文案与文件夹已一一配对`)));
        matchHint.style.color = autoEditBatchTasks.length && extraCount && !autoEditBatchSmartPairingComplete ? '#ff9f43' : '';
    }
    if (!autoEditBatchTasks.length) {
        if (!autoEditBatchScriptCells.length) { root.innerHTML = '<div class="hint">先粘贴 Google Sheets 单元格，或先选择多个文件夹。</div>'; return; }
        root.innerHTML = autoEditBatchScriptCells.map((script, i) => {
            const lines = script.split(/\r?\n/).filter(line => line.trim()).length;
            return `<div style="border:1px solid rgba(99,102,241,.3);border-radius:8px;padding:10px;background:rgba(99,102,241,.07);"><div style="display:flex;justify-content:space-between;gap:8px;margin-bottom:6px;"><strong style="color:#a5b4fc;">文案单元格 #${i+1}</strong><span class="hint">${lines} 行</span></div><div style="white-space:pre-wrap;line-height:1.5;max-height:120px;overflow:auto;color:var(--text-primary);">${escapeHtml(script) || '<span style="color:#ff9f43;">空单元格（保留位置）</span>'}</div></div>`;
        }).join('');
        return;
    }
    const colors = { waiting:'#8b95c0', analyzing:'#4dabf7', ready:'#51cf66', reviewed:'#86efac', exported:'#60a5fa', warning:'#ff9f43', error:'#ff6b6b', cancelled:'#fbbf24', skipped:'#94a3b8' };
    const taskCards = autoEditBatchTasks.map((task, i) => {
        if (task.status === 'analyzing' && task.progress) {
            task.message = formatAutoEditBatchLiveMessage(task.progress, task.progressUpdatedAt);
        }
        const lines = task.script.split(/\r?\n/).filter(x => x.trim()).length;
        const first = task.clips[0]?.split(/[/\\]/).pop() || '没有视频';
        const analysisResultHtml = renderAutoEditBatchMatchResult(task);
        const smartPairHtml = Number.isFinite(task.smartPairScore)
            ? `<span title="原粘贴文案 #${Number(task.smartPairScriptIndex) + 1}；分数综合词汇与相邻词顺序" style="color:${task.smartPairScore >= .55 ? '#86efac' : (task.smartPairScore >= .35 ? '#fcd34d' : '#fca5a5')};font-weight:700;">🧠 文案 #${Number(task.smartPairScriptIndex) + 1} · ${Math.round(task.smartPairScore * 100)}%</span>`
            : '';
        const outputSourceHtml = task.result?.output_path
            ? `<div title="${escapeHtml(task.result.output_path)}" style="margin-top:6px;padding:5px 7px;border-radius:5px;background:rgba(59,130,246,.08);color:#93c5fd;font-size:10px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">📍 Reels 成片来源：${escapeHtml(task.result.output_path)}</div>${(task.reviewSegments?.length || task.result?.review_segments?.length) ? `<button class="btn btn-primary" onclick="openAutoEditBatchTimelineReview(${i})" ${autoEditBatchRunning?'disabled':''} style="margin-top:6px;">⏱ 继续时间线审核</button>` : ''}`
            : '';
        return `<div class="autoedit-batch-task" ondragover="event.preventDefault()" ondrop="autoEditBatchDrop(event,${i})" style="border:1px solid var(--border-color);border-radius:8px;padding:10px;background:var(--bg-tertiary);display:grid;grid-template-columns:128px minmax(0,1fr);gap:10px;">
          <div style="width:128px;align-self:start;">${task.thumbnail ? `<div style="width:128px;display:flex;justify-content:center;align-items:center;background:#111;border-radius:6px;overflow:hidden;"><img src="${task.thumbnail}" onclick="playAutoEditBatchSource(${i})" style="display:block;max-width:128px;width:auto;height:auto;max-height:180px;object-fit:contain;cursor:pointer;" title="按原始视频比例显示，点击预览"></div>` : '<div style="width:128px;height:82px;background:#111;border-radius:6px;display:grid;place-items:center;color:#777;">无缩略图</div>'}<div title="${escapeHtml(first)}" style="font-size:10px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-top:4px;">${escapeHtml(first)}</div></div>
          <div><div style="display:flex;justify-content:space-between;gap:8px;align-items:center;"><div style="display:flex;gap:5px;align-items:center;flex-wrap:wrap;"><label title="输入目标顺序编号后回车或点击空白处" style="display:inline-flex;align-items:center;gap:4px;padding:3px 6px;border:1px solid rgba(99,102,241,.5);border-radius:6px;background:rgba(99,102,241,.12);font-size:11px;color:#c7d2fe;">顺序 <input type="number" min="1" max="${autoEditBatchTasks.length}" value="${i+1}" onchange="setAutoEditBatchTaskOrder(${i},this.value)" onkeydown="if(event.key==='Enter'){this.blur()}" ${autoEditBatchRunning?'disabled':''} style="width:46px;background:#111225;color:#fff;border:1px solid rgba(255,255,255,.18);border-radius:4px;padding:2px 4px;text-align:center;"></label><span draggable="true" ondragstart="autoEditBatchDragStart(event,${i})" title="拖动排序" style="cursor:grab;font-size:18px;">☰</span><button class="btn btn-secondary" title="上移一位" onclick="nudgeAutoEditBatchTask(${i},-1)" ${autoEditBatchRunning||i===0?'disabled':''} style="padding:1px 5px;">↑</button><button class="btn btn-secondary" title="下移一位" onclick="nudgeAutoEditBatchTask(${i},1)" ${autoEditBatchRunning||i===autoEditBatchTasks.length-1?'disabled':''} style="padding:1px 5px;">↓</button><strong>${escapeHtml(task.name)}</strong>${smartPairHtml}</div><span title="${escapeHtml(task.reelsTransferError || task.message)}" style="color:${colors[task.status] || '#8b95c0'};font-size:12px;line-height:1.55;white-space:pre-line;">${escapeHtml(task.message)}</span></div><div class="hint">直接修改顺序编号可快速移动 · ${task.clips.length} 个视频 · ${lines} 行断行文案</div><div style="display:flex;align-items:center;gap:12px;margin-top:7px;flex-wrap:wrap;"><label style="display:flex;align-items:center;gap:7px;font-size:11px;flex:1;min-width:250px;"><strong style="min-width:76px;color:#c7d2fe;">🏷️ 导出名称</strong><input class="input" value="${escapeHtml(task.outputName || task.name)}" placeholder="Reels 中的任务名和最终文件名" onchange="updateAutoEditBatchOutputName(${i},this.value)" ${autoEditBatchRunning?'disabled':''} style="flex:1;"></label><label title="未勾选的任务不会裁切、不会生成视频或字幕，也不会送入 Reels" style="display:inline-flex;align-items:center;gap:5px;color:#a7f3d0;font-size:11px;white-space:nowrap;"><input type="checkbox" onchange="updateAutoEditBatchSendToReels(${i},this.checked)" ${task.sendToReels === false ? '' : 'checked'} ${autoEditBatchRunning?'disabled':''}> 参与本次导出</label></div><label style="display:block;margin-top:8px;"><strong style="display:block;font-size:11px;color:#bfdbfe;margin-bottom:4px;">📝 当前任务的完整断行后文案 <span class="hint" style="font-weight:400;">（用于字幕匹配和自动剪辑）</span></strong><textarea class="input" rows="3" placeholder="在这里输入或修改已经断好行的完整文案……" onchange="updateAutoEditBatchScript(${i},this.value)" ${autoEditBatchRunning?'disabled':''} style="width:100%;resize:vertical;background:var(--bg-secondary);">${escapeHtml(task.script)}</textarea></label>${analysisResultHtml}${outputSourceHtml}${task.result?.analysis_only ? `<div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px;align-items:center;"><button class="btn btn-primary" onclick="openAutoEditBatchTimelineReview(${i})" ${autoEditBatchRunning?'disabled':''} style="font-size:12px;padding:4px 10px;">⏱ 时间线审核</button><button class="btn btn-secondary" onclick="openAutoEditBatchReview(${i})" ${autoEditBatchRunning?'disabled':''} style="font-size:12px;padding:4px 10px;">📋 列表审核</button><button class="btn btn-primary" onclick="exportAutoEditBatchTask(${i})" ${autoEditBatchRunning||task.status==='analyzing'?'disabled':''} style="font-size:12px;padding:4px 10px;">正式导出</button><button class="btn btn-secondary" onclick="exportAutoEditBatchTask(${i},{skipReels:true})" ${autoEditBatchRunning||task.status==='analyzing'?'disabled':''} style="font-size:12px;padding:4px 10px;">仅视频 + 字幕</button></div>` : ''}${task.result?.output_path ? `<button class="btn btn-secondary" onclick="showAutoEditBatchOutput(${i})" style="margin-top:6px;">📁 查看成片</button>${task.reelsTransferError ? `<button class="btn btn-secondary" onclick="retryAutoEditBatchTaskToReels(${i})" ${autoEditBatchRunning?'disabled':''} style="margin:6px 0 0 6px;">重送 Reels</button>` : ''}` : ''}</div>
        </div>`;
    }).join('');
    const unmatchedCards = autoEditBatchUnmatchedScripts.length ? `<section style="grid-column:1/-1;border:1px solid rgba(251,191,36,.45);border-radius:9px;padding:12px;background:rgba(251,191,36,.06);">
        <div style="display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:8px;"><strong style="color:#fcd34d;">📄 未匹配文案（${autoEditBatchUnmatchedScripts.length}）</strong><span class="hint">保留但不分析、不裁切、不导出</span></div>
        <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:8px;">${autoEditBatchUnmatchedScripts.map((item, index) => {
            const script = String(item.script || '');
            const lines = script.split(/\r?\n/).filter(line => line.trim()).length;
            return `<div style="border:1px solid rgba(251,191,36,.25);border-radius:7px;padding:8px;background:rgba(0,0,0,.16);"><div style="display:flex;justify-content:space-between;gap:8px;margin-bottom:5px;"><strong style="color:#fde68a;">原文案 #${Number(item.originalIndex) + 1}</strong><span class="hint">${lines} 行</span></div><div style="white-space:pre-wrap;line-height:1.45;max-height:100px;overflow:auto;">${escapeHtml(script)}</div></div>`;
        }).join('')}</div></section>` : '';
    root.innerHTML = taskCards + unmatchedCards;
    hydrateAutoEditBatchReviewThumbnails(root);
    root.querySelectorAll('.autoedit-batch-task').forEach((card, index) => {
        const task = autoEditBatchTasks[index];
        if (autoEditBatchTaskFilter === 'issues') {
            card.hidden = !autoEditBatchTaskHasIssues(task);
        } else if (autoEditBatchTaskFilter === 'passed') {
            card.hidden = autoEditBatchTaskHasIssues(task);
        } else if (autoEditBatchTaskFilter === 'handled') {
            card.hidden = !autoEditBatchTaskIsHandledPassed(task);
        } else if (autoEditBatchTaskFilter === 'unexported') {
            card.hidden = !autoEditBatchTaskIsUnexported(task);
        } else if (autoEditBatchTaskFilter === 'selected') {
            card.hidden = task?.sendToReels === false;
        } else {
            card.hidden = false;
        }
        if (card.hidden) card.style.display = 'none';
        else card.style.display = '';
        const button = document.createElement('button');
        button.className = 'btn btn-secondary';
        button.textContent = '↻ 刷新文件夹并分析';
        button.disabled = autoEditBatchRunning;
        button.onclick = () => refreshAutoEditBatchTaskFolder(index);
        card.lastElementChild?.append(button);
    });

    const filterPassedBtn = document.getElementById('autoedit-batch-filter-passed-btn');
    const filterHandledBtn = document.getElementById('autoedit-batch-filter-handled-btn');
    const filterIssuesBtn = document.getElementById('autoedit-batch-filter-issues-btn');
    const filterSelectedBtn = document.getElementById('autoedit-batch-filter-selected-btn');
    const filterUnexportedBtn = document.getElementById('autoedit-batch-filter-unexported-btn');
    const filterAllBtn = document.getElementById('autoedit-batch-filter-all-btn');
    const issuesCount = autoEditBatchTasks.filter(t => autoEditBatchTaskHasIssues(t)).length;
    const passedCount = autoEditBatchTasks.filter(t => Boolean(t?.clips?.length) && !autoEditBatchTaskHasIssues(t)).length;
    const handledCount = autoEditBatchTasks.filter(autoEditBatchTaskIsHandledPassed).length;
    const selectedCount = autoEditBatchTasks.filter(t => t.sendToReels !== false).length;
    const unexportedCount = autoEditBatchTasks.filter(autoEditBatchTaskIsUnexported).length;
    const allCount = autoEditBatchTasks.length;

    if (filterPassedBtn) {
        filterPassedBtn.textContent = `查看通过 (${passedCount})`;
        filterPassedBtn.classList.toggle('btn-primary', autoEditBatchTaskFilter === 'passed');
        filterPassedBtn.classList.toggle('btn-secondary', autoEditBatchTaskFilter !== 'passed');
    }
    if (filterHandledBtn) {
        filterHandledBtn.textContent = `查看修改后合格 (${handledCount})`;
        filterHandledBtn.classList.toggle('btn-primary', autoEditBatchTaskFilter === 'handled');
        filterHandledBtn.classList.toggle('btn-secondary', autoEditBatchTaskFilter !== 'handled');
    }
    if (filterIssuesBtn) {
        filterIssuesBtn.textContent = `查看未通过 (${issuesCount})`;
        filterIssuesBtn.classList.toggle('btn-primary', autoEditBatchTaskFilter === 'issues');
        filterIssuesBtn.classList.toggle('btn-secondary', autoEditBatchTaskFilter !== 'issues');
    }
    if (filterSelectedBtn) {
        filterSelectedBtn.textContent = `查看已选择 (${selectedCount})`;
        filterSelectedBtn.classList.toggle('btn-primary', autoEditBatchTaskFilter === 'selected');
        filterSelectedBtn.classList.toggle('btn-secondary', autoEditBatchTaskFilter !== 'selected');
    }
    if (filterUnexportedBtn) {
        filterUnexportedBtn.textContent = `查看未导出 (${unexportedCount})`;
        filterUnexportedBtn.classList.toggle('btn-primary', autoEditBatchTaskFilter === 'unexported');
        filterUnexportedBtn.classList.toggle('btn-secondary', autoEditBatchTaskFilter !== 'unexported');
    }
    if (filterAllBtn) {
        filterAllBtn.textContent = `显示全部 (${allCount})`;
        filterAllBtn.classList.toggle('btn-primary', autoEditBatchTaskFilter === 'all');
        filterAllBtn.classList.toggle('btn-secondary', autoEditBatchTaskFilter !== 'all');
    }
}
function playAutoEditBatchSource(index) {
    const source = autoEditBatchTasks[index]?.clips?.[0];
    if (source) window.playVideoClip(source, 0, 0);
}

async function analyzeAutoEditBatchTask(task, settings = task.settings || getAutoEditRequestSettings()) {
    if (autoEditBatchStopRequested) {
        task.status = 'cancelled';
        task.message = '已停止（未开始上传或识别）';
        renderAutoEditBatchTasks();
        return;
    }
    flushAutoEditProjectReview();
    const previousResult = findAutoEditBatchReviewProject(task, settings) || task.result;
    const reviewSource = task.reviewSegments?.length ? task.reviewSegments
        : (previousResult?.review_segments?.length ? previousResult.review_segments : previousResult?.segments || []);
    const savedReviews = reviewSource.map(item => ({ ...item }));
    task.status='analyzing'; task.progress={ stage:'start', current:0, total:task.clips?.length || 0 }; task.message='准备语音识别'; renderAutoEditBatchTasks();
    const requestId=`autoedit-batch-analysis-${Date.now()}-${Math.random().toString(36).slice(2)}`;
    autoEditActiveRequestIds.add(requestId);
    document.getElementById('autoedit-batch-stop-btn')?.removeAttribute('disabled');
    const unsubscribe=window.electronAPI?.onAutoEditProgress?.(progress=>{
        if(progress?.request_id!==requestId)return;
        task.progress = { ...progress };
        task.progressUpdatedAt = Date.now();
        task.message = formatAutoEditBatchLiveMessage(progress, task.progressUpdatedAt); renderAutoEditBatchTasks();
    });
    try {
        task.settings={...settings, ...getAutoEditTranscriptionOverride('batch')};
        const response = await apiFetch(`${API_BASE}/media/convert`, { method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({ files:task.clips, clips:task.clips, mode:'auto_edit', request_id:requestId, analysis_only:true, script_text:task.script, output_dir:window.electronAPI.pathJoin(task.folder,'_auto_edit'), manual_subtitle_map: task.manualSubtitleMap || {}, ...task.settings }) });
        const data = await response.json(); if (!response.ok) throw new Error(data.error || '分析失败');
        // 重分析刷新识别底稿，但不能清空同路径片段的人工审核结果。
        // 只覆盖 ASR、匹配证据与状态；人工编辑字段由审核快照保留。
        const savedBySource = new Map(savedReviews.filter(item => item?.source && hasAutoEditHumanReview(item))
            .map(item => [String(item.source).replace(/\\/g, '/'), item]));
        if (savedBySource.size) {
            data.segments = (data.segments || []).map(segment => {
                const saved = savedBySource.get(String(segment.source || '').replace(/\\/g, '/'));
                return saved ? { ...segment, ...saved, source: segment.source, source_index: segment.source_index, index: segment.index, recognized_text: segment.recognized_text, word_timeline: segment.word_timeline, status: segment.status, issue_reason: segment.issue_reason } : segment;
            });
            task.reviewSegments = data.segments.map(segment => ({ ...segment }));
            data.review_segments = task.reviewSegments.map(segment => ({ ...segment }));
        } else task.reviewSegments = null;
        const restoredMissingAssignments = restoreAutoEditMissingBlockAssignments(data, previousResult);
        reconcileAutoEditMissingBlocks(data, data.segments);
        data.clips = task.clips.slice();
        data.script_text = task.script;
        task.restoredReviewCount = (data.segments || []).filter(segment => savedBySource.has(String(segment.source || '').replace(/\\/g, '/'))).length + restoredMissingAssignments;
        if (task.restoredReviewCount && data.project_path) {
            saveAutoEditReviewProject(data, task.settings);
        }
        task.result=data;
        const match = getAutoEditBatchMatchSummary(data);
        const finalStatus = getAutoEditBatchFinalStatus(data);
        task.status = match.error > 0 ? 'error' : ((match.warning > 0 || match.missingBlocks > 0) ? 'warning' : 'ready');
        task.message = `${finalStatus.recognition}\n${finalStatus.matching}\n${finalStatus.coverage}${task.restoredReviewCount ? `\n已沿用 ${task.restoredReviewCount} 项历史审核` : ''}`;
    } catch (e) {
        const cancelled = /任务已停止|已收到停止指令/.test(String(e?.message || ''));
        task.status = cancelled ? 'cancelled' : 'error';
        task.message = cancelled ? '已停止分析（未完成的片段不会继续上传或识别）' : e.message;
    }
    finally { autoEditActiveRequestIds.delete(requestId); if(typeof unsubscribe==='function')unsubscribe(); setAutoEditBatchRunning(autoEditBatchRunning); }
    renderAutoEditBatchTasks();
    saveAutoEditWorkspaceState();
}

function scoreAutoEditBatchSmartPair(transcript, script) {
    const normalize = text => autoEditWords(text).map(word => String(word).toLocaleLowerCase().normalize('NFKC').replace(/[^\p{L}\p{N}]/gu, '')).filter(Boolean);
    const a = normalize(transcript), b = normalize(script);
    if (!a.length || !b.length) return 0;
    const counts = words => words.reduce((map, word) => (map.set(word, (map.get(word) || 0) + 1), map), new Map());
    const ac = counts(a), bc = counts(b);
    let dot = 0, aa = 0, bb = 0;
    ac.forEach(value => { aa += value * value; });
    ac.forEach((value, key) => { dot += value * (bc.get(key) || 0); });
    bc.forEach(value => { bb += value * value; });
    const cosine = dot / Math.max(1, Math.sqrt(aa * bb));
    const bigrams = words => {
        const map = new Map();
        for (let i = 0; i + 1 < words.length; i++) {
            const key = `${words[i]}\u0001${words[i + 1]}`;
            map.set(key, (map.get(key) || 0) + 1);
        }
        return map;
    };
    const ab = bigrams(a), bbm = bigrams(b);
    let overlap = 0, totalA = 0, totalB = 0;
    ab.forEach((value, key) => { totalA += value; overlap += Math.min(value, bbm.get(key) || 0); });
    bbm.forEach(value => { totalB += value; });
    const dice = totalA + totalB ? (2 * overlap / (totalA + totalB)) : cosine;
    const lengthRatio = Math.min(a.length, b.length) / Math.max(a.length, b.length);
    return Math.max(0, Math.min(1, (.62 * cosine + .38 * dice) * (.82 + .18 * lengthRatio)));
}

// Hungarian assignment: returns the script index chosen for every task while
// Hungarian assignment: returns the script index chosen for every task while
// maximizing the complete matrix score, rather than greedily stealing the best
// script from a later task.
function solveAutoEditBatchSmartAssignment(scores) {
    const rowCount = scores.length;
    const columnCount = scores.reduce((max, row) => Math.max(max, row.length), 0);
    if (!rowCount || !columnCount) return new Array(rowCount).fill(-1);

    // 当文案数量少于任务数量时（例如存在空单元格导致有效文案少于任务数）：
    // 通过转置矩阵为每个文案选出全局匹配度最高的任务，未分配到文案的任务置为 -1
    if (columnCount < rowCount) {
        const transposed = Array.from({ length: columnCount }, (_, j) =>
            Array.from({ length: rowCount }, (_, i) => scores[i]?.[j] ?? 0)
        );
        const scriptToTask = solveAutoEditBatchSmartAssignment(transposed);
        const assignment = new Array(rowCount).fill(-1);
        scriptToTask.forEach((taskIdx, scriptIdx) => {
            if (taskIdx >= 0 && taskIdx < rowCount) {
                assignment[taskIdx] = scriptIdx;
            }
        });
        return assignment;
    }

    const u = new Float64Array(rowCount + 1), v = new Float64Array(columnCount + 1);
    const p = new Int32Array(columnCount + 1), way = new Int32Array(columnCount + 1);
    for (let i = 1; i <= rowCount; i++) {
        p[0] = i;
        let j0 = 0;
        const minv = new Float64Array(columnCount + 1); minv.fill(Infinity);
        const used = new Uint8Array(columnCount + 1);
        do {
            used[j0] = 1;
            const i0 = p[j0];
            let delta = Infinity, j1 = 0;
            for (let j = 1; j <= columnCount; j++) if (!used[j]) {
                const cur = (1 - (scores[i0 - 1]?.[j - 1] ?? 0)) - u[i0] - v[j];
                if (cur < minv[j]) { minv[j] = cur; way[j] = j0; }
                if (minv[j] < delta) { delta = minv[j]; j1 = j; }
            }
            for (let j = 0; j <= columnCount; j++) {
                if (used[j]) { u[p[j]] += delta; v[j] -= delta; }
                else minv[j] -= delta;
            }
            j0 = j1;
        } while (p[j0] !== 0);
        do { const j1 = way[j0]; p[j0] = p[j1]; j0 = j1; } while (j0);
    }
    const assignment = new Array(rowCount).fill(-1);
    for (let j = 1; j <= columnCount; j++) if (p[j]) assignment[p[j] - 1] = j - 1;
    return assignment;
}

async function startAutoEditBatchSmartPairing() {
    if (autoEditBatchRunning) return showToast('批量任务正在运行，请稍候', 'info');
    // 空文案单元格不参与智能匹配；它们常常对应未就绪文案或被跳过的任务
    const scriptItems = autoEditBatchScriptCells
        .map((script, originalIndex) => ({ script: String(script || ''), originalIndex }))
        .filter(item => item.script.trim());
    const scripts = scriptItems.map(item => item.script);
    if (!scripts.length) return showToast('没有检测到有效文案，请先粘贴文案', 'error');
    if (!autoEditBatchTasks.length) return showToast('请先添加任务文件夹', 'error');

    const activeTasks = autoEditBatchTasks.filter(task => task.clips?.length);
    const skippedTasks = autoEditBatchTasks.filter(task => !task.clips?.length);
    skippedTasks.forEach(task => {
        task.status = 'skipped';
        task.sendToReels = false;
        task.message = '空文件夹，已跳过';
    });
    if (!activeTasks.length) { renderAutoEditBatchTasks(); return showToast('所有任务文件夹都没有视频，已在对应卡片标记为跳过', 'warning'); }

    const isFewerScripts = scripts.length < activeTasks.length;
    const concurrency = Math.max(1, Math.min(4, parseInt(document.getElementById('autoedit-batch-concurrency')?.value || '2', 10)));
    const settings = { ...getAutoEditRequestSettings() };
    autoEditBatchStopRequested = false;
    setAutoEditBatchRunning(true);
    showToast(isFewerScripts
        ? `智能配对：检测到 ${scripts.length} 个有效文案（缺少 ${activeTasks.length - scripts.length} 个），正在智能寻找最佳匹配任务组合…`
        : '智能配对：正在取得每个文件夹的识别全文…', 'info', 5000);
    try {
        const transcriptForTask = task => (task.result?.segments || [])
            .slice()
            .sort((a, b) => Number(a.source_index || a.index) - Number(b.source_index || b.index))
            .map(segment => segment.recognized_text || '').join(' ').trim();
        const analyzedScripts = activeTasks.map(task => task.script);
        let cursor = 0;
        const transcribeWorker = async () => {
            while (!autoEditBatchStopRequested && cursor < activeTasks.length) {
                const task = activeTasks[cursor++];
                if (transcriptForTask(task)) {
                    task.message = '智能配对 · 已复用现有识别结果';
                    renderAutoEditBatchTasks();
                    continue;
                }
                task.message = '智能配对 · 正在识别全文';
                await analyzeAutoEditBatchTask(task, settings);
            }
        };
        await Promise.all(Array.from({ length: Math.min(concurrency, activeTasks.length) }, transcribeWorker));
        if (autoEditBatchStopRequested) {
            showToast('本批次已停止：其余任务不会继续进行智能配对或识别。', 'warning');
            return;
        }
        const transcripts = activeTasks.map(transcriptForTask);
        const missingTranscript = transcripts.findIndex(text => !text);
        if (missingTranscript >= 0) throw new Error(`${activeTasks[missingTranscript].name} 没有取得有效识别文字`);
        const scores = transcripts.map(transcript => scripts.map(script => scoreAutoEditBatchSmartPair(transcript, script)));
        const assignment = solveAutoEditBatchSmartAssignment(scores);
        const assignedScriptIndexes = new Set();
        assignment.forEach(idx => { if (idx >= 0) assignedScriptIndexes.add(idx); });

        const tasksNeedingVerification = [];
        let unassignedCount = 0;
        activeTasks.forEach((task, index) => {
            const scriptIndex = assignment[index];
            if (scriptIndex >= 0 && scripts[scriptIndex]) {
                const assignedScript = scripts[scriptIndex];
                const canReuseAnalysis = task.result?.analysis_only === true && analyzedScripts[index] === assignedScript;
                task.script = assignedScript;
                task.smartPairScriptIndex = scriptItems[scriptIndex].originalIndex;
                task.smartPairScore = scores[index][scriptIndex];
                task.sendToReels = true;
                if (canReuseAnalysis) {
                    task.message = `智能配对到文案 #${scriptIndex + 1} · ${Math.round(task.smartPairScore * 100)}% · 已复用分析`;
                } else {
                    task.reviewSegments = null;
                    task.result = null;
                    task.status = 'waiting';
                    task.message = `智能配对到文案 #${scriptIndex + 1} · ${Math.round(task.smartPairScore * 100)}% · 等待复核`;
                    tasksNeedingVerification.push(task);
                }
            } else {
                task.script = '';
                task.smartPairScriptIndex = null;
                task.smartPairScore = null;
                task.reviewSegments = null;
                task.result = null;
                task.status = 'skipped';
                task.sendToReels = false;
                task.message = '空单元格无对应文案（已跳过导出）';
                unassignedCount++;
            }
        });
        autoEditBatchUnmatchedScripts = scriptItems
            .filter((item, compactIndex) => !assignedScriptIndexes.has(compactIndex))
            .map(item => ({ ...item, confirmed: true }));
        autoEditBatchSmartPairingComplete = true;
        syncAutoEditBatchParallelLists();
        renderAutoEditBatchTasks();
        showToast(tasksNeedingVerification.length
            ? `文案已重新分配；${activeTasks.length - unassignedCount - tasksNeedingVerification.length} 个任务直接复用，正在复核 ${tasksNeedingVerification.length} 个变化任务…${unassignedCount ? `；已跳过 ${unassignedCount} 个空文案任务` : ''}`
            : `智能配对完成；有效任务均复用现有分析${unassignedCount ? `；已自动跳过 ${unassignedCount} 个空文案任务` : ''}`, 'info', 6000);
        cursor = 0;
        const verifyWorker = async () => {
            while (!autoEditBatchStopRequested && cursor < tasksNeedingVerification.length) await analyzeAutoEditBatchTask(tasksNeedingVerification[cursor++], settings);
        };
        await Promise.all(Array.from({ length: Math.min(concurrency, tasksNeedingVerification.length) }, verifyWorker));
        if (autoEditBatchStopRequested) {
            showToast('本批次已停止：其余任务不会继续复核。', 'warning');
            return;
        }
        const lowConfidence = activeTasks.filter(task => task.script && task.smartPairScore < .35).length;
        const unmatchedCount = autoEditBatchUnmatchedScripts.length;
        showToast(lowConfidence
            ? `智能配对完成；${lowConfidence} 组置信度较低，请人工确认${unmatchedCount ? `；${unmatchedCount} 个文案未匹配` : ''}`
            : `智能配对并复核完成${unmatchedCount ? `；${unmatchedCount} 个多余文案已列为未匹配` : ''}${unassignedCount ? `；已跳过 ${unassignedCount} 个空文案任务` : ''}${skippedTasks.length ? `；已跳过 ${skippedTasks.length} 个空文件夹` : ''}`, lowConfidence ? 'warning' : 'success', 7000);
    } catch (error) {
        showToast(`智能配对失败：${error?.message || error}`, 'error', 7000);
    } finally {
        setAutoEditBatchRunning(false);
    }
}

function autoEditBatchProjectFileNames(settings = {}) {
    const preferred = settings.matching_engine === 'compare_v2'
        ? 'auto_edit_comparison_project.json'
        : (settings.matching_engine === 'legacy' ? 'auto_edit_project.json' : 'auto_edit_project_v2.json');
    return ['auto_edit_review_history.json', preferred, 'auto_edit_project_v2.json', 'auto_edit_comparison_project.json', 'auto_edit_project.json']
        .filter((name, index, list) => list.indexOf(name) === index);
}

function findAutoEditBatchReviewProject(task, settings = {}) {
    // 当前列表内已有审核快照时优先使用它；这也是“不重新拖入、直接再分析”
    // 的情况。重新拖入后 task 是新的，才会继续查 _auto_edit 的工程文件。
    if (Array.isArray(task?.result?.segments) && autoEditBatchProjectHasHumanReview(task.result)) return task.result;
    if (!task?.folder || !window.electronAPI?.readFileText || !window.electronAPI?.pathJoin) return null;
    const currentClips = new Set((task.clips || []).map(path => String(path).replace(/\\/g, '/')));
    for (const fileName of autoEditBatchProjectFileNames(settings)) {
        try {
            const raw = window.electronAPI.readFileText(window.electronAPI.pathJoin(task.folder, '_auto_edit', fileName));
            if (!raw) continue;
            const project = JSON.parse(raw);
            if (!Array.isArray(project?.segments)) continue;
            // 兼容旧版审核保存漏写 clips 的工程，从片段恢复素材清单。
            if (!Array.isArray(project.clips) || !project.clips.length) {
                project.clips = [...new Set(project.segments.map(segment => segment.source).filter(Boolean))];
            }
            // 不能只因“有一个素材相同”就把旧审核结果带回来：同一目录重新
            // 分批处理时会串任务。但素材增删时，仍须保留未改变片段的人工处理。
            // 因此要求素材集合有显著重合；真正回填时还会再次按每个片段的完整
            // 路径匹配，所以新增素材不会继承旧状态，已删除素材也不会被带入。
            const savedClips = new Set(project.clips.map(path => String(path).replace(/\\/g, '/')));
            const sharedSourceCount = [...savedClips].filter(path => currentClips.has(path)).length;
            const smallerSetSize = Math.min(savedClips.size, currentClips.size);
            const overlapRatio = smallerSetSize ? sharedSourceCount / smallerSetSize : 0;
            const isSameTaskFamily = sharedSourceCount > 0 && overlapRatio >= 0.7;
            if (isSameTaskFamily && autoEditBatchProjectHasHumanReview(project)) return project;
        } catch (error) {
            console.warn('[文案自动剪辑] 读取旧审核工程失败:', error);
        }
    }
    return null;
}

function autoEditBatchProjectHasHumanReview(project) {
    return Boolean((project?.segments || []).some(hasAutoEditHumanReview)
        || (project?.missing_blocks || []).some(block => block?.review_assignment));
}

async function startAutoEditBatchAnalysis() {
    if(autoEditBatchRunning)return showToast('批量任务正在运行，请稍候','info');
    if (!autoEditBatchTasks.length) return showToast('请先选择多个文件夹','error');
    const activeTasks = autoEditBatchTasks.filter(task => task.clips?.length);
    const skippedTasks = autoEditBatchTasks.filter(task => !task.clips?.length);
    skippedTasks.forEach(task => { task.status = 'skipped'; task.sendToReels = false; task.message = '空文件夹，已跳过'; });
    if (!activeTasks.length) { renderAutoEditBatchTasks(); return showToast('没有可分析的视频任务', 'warning'); }

    // 缺少文案的任务自动跳过，不阻碍其他正常任务
    const missingScriptTasks = activeTasks.filter(t => !t.script?.trim());
    missingScriptTasks.forEach(t => {
        t.status = 'skipped';
        t.sendToReels = false;
        t.message = '无文案（空单元格已跳过）';
    });

    const tasksToAnalyze = activeTasks.filter(t => t.script?.trim() && t.sendToReels !== false);
    if (!tasksToAnalyze.length) {
        renderAutoEditBatchTasks();
        return showToast('没有可分析的有效任务（所有任务均缺少文案或已跳过）', 'warning');
    }

    if (autoEditBatchScriptCells.length > activeTasks.length && !autoEditBatchSmartPairingComplete) {
        return showToast(`文案多于有视频任务，请先点击「智能配对」自动选择匹配文案`,'error',6500);
    }

    const n=Math.max(1,Math.min(4,parseInt(document.getElementById('autoedit-batch-concurrency')?.value||'2',10))); let cursor=0;
    autoEditBatchStopRequested = false;
    const settings={...getAutoEditRequestSettings()};
    // 所有分析入口统一在 analyzeAutoEditBatchTask 中自动恢复审核记录。
    setAutoEditBatchRunning(true);
    try {
        const worker=async()=>{ while(!autoEditBatchStopRequested && cursor<tasksToAnalyze.length) await analyzeAutoEditBatchTask(tasksToAnalyze[cursor++],settings); };
        await Promise.all(Array.from({length:Math.min(n,tasksToAnalyze.length)},worker));
        if (autoEditBatchStopRequested) {
            showToast('批量分析已停止：未启动的任务不会继续识别。', 'warning');
            return;
        }
        const taskErrors=autoEditBatchTasks.filter(task=>task.status==='error').length;
        const taskWarnings=autoEditBatchTasks.filter(task=>task.status==='warning').length;
        const totals=autoEditBatchTasks.reduce((acc,task)=>{
            if (!task.result?.analysis_only) return acc;
            const item=getAutoEditBatchTaskSummary(task);
            acc.ready+=item.ready; acc.warning+=item.warning; acc.error+=item.error; acc.missing+=item.missingBlocks;
            return acc;
        },{ready:0,warning:0,error:0,missing:0});
        const detail=`${totals.ready} 个片段通过，${totals.warning} 个警告，${totals.error} 个失败${totals.missing?`，${totals.missing} 段文案缺失`:''}`;
        showToast(`批量分析完成：${detail}`,taskErrors?'error':(taskWarnings?'warning':'success'));
        playAutoEditBatchCompletionSound(taskErrors === 0);
    } finally { setAutoEditBatchRunning(false); }
}
function autoEditBatchExportSignature(task) {
    const review = task.reviewSegments || task.result?.review_segments || task.result?.segments || [];
    return JSON.stringify({
        clips: (task.clips || []).map(path => String(path)),
        script: String(task.script || ''),
        outputName: String(task.outputName || task.name || ''),
        review: review.map(segment => ({
            source: segment.source, enabled: segment.enabled !== false, script: segment.script,
            start: Number(segment.start), end: Number(segment.end), speed: Number(segment.speed || 1),
            cut: segment.cut_selection || '', scale: Number(segment.visual_scale || 100), subtitles: segment.manual_subtitles || [],
            isHook: segment.is_hook === true, hookKeepAudio: segment.hook_keep_audio !== false,
            removeRanges: segment.visual_remove_ranges || []
        }))
    });
}
function autoEditBatchExportIsCurrent(task) {
    return Boolean(task?.result?.output_path && task.exportSignature && task.exportSignature === autoEditBatchExportSignature(task));
}
async function exportAutoEditBatchTask(index, options = {}) {
    if (autoEditActiveBatchIndex === index) persistAutoEditBatchReview();
    const task = autoEditBatchTasks[index];
    if (!task?.result?.analysis_only) return showToast('请先完成该任务的分析', 'error');
    if (autoEditBatchExportIsCurrent(task)) {
        task.status = 'exported'; task.message = '已导出（未修改，已跳过）'; renderAutoEditBatchTasks();
        return showToast(`${task.name} 未修改，保留已有导出`, 'info');
    }
    const ownsLock = options.managed !== true;
    if (ownsLock && autoEditBatchRunning) return showToast('批量任务正在运行，请稍候', 'info');
    if(task.status==='analyzing')return;
    if (ownsLock) setAutoEditBatchRunning(true);
    task.status='analyzing'; task.message='正在正式导出'; renderAutoEditBatchTasks();
    const requestId=`autoedit-batch-export-${Date.now()}-${Math.random().toString(36).slice(2)}`;
    autoEditActiveRequestIds.add(requestId);
    document.getElementById('autoedit-batch-stop-btn')?.removeAttribute('disabled');
    const unsubscribe=window.electronAPI?.onAutoEditProgress?.(progress=>{
        if(progress?.request_id!==requestId)return;
        task.message=progress.message||'正在正式导出'; renderAutoEditBatchTasks();
    });
    try {
        let exportStage = '准备审核时间线';
        let exportedData = null;
        try {
            const reviewSegments=(task.reviewSegments?.length ? task.reviewSegments : (task.result.review_segments?.length ? task.result.review_segments : (task.result.segments || []))).map(seg=>({
                ...seg,
                segment_id:seg.segment_id,
                source:seg.source,
                source_index:Number(seg.source_index),
                enabled:seg.enabled !== false,
                script:seg.script,
                start:Number(seg.start),
                end:Number(seg.end),
                cut_selection:seg.cut_selection||'classic',
                classic_start:Number(seg.legacy_start??seg.start),
                classic_end:Number(seg.legacy_end??seg.end),
                v2_start:Number(seg.v2_start??seg.start),
                v2_end:Number(seg.v2_end??seg.end),
                speed:Number(seg.speed)||1,
                visual_scale:Number(seg.visual_scale)||100,
                manual_subtitles:Array.isArray(seg.manual_subtitles) ? seg.manual_subtitles : []
            }));
            // 批量任务可能在列表审核中手动补入“已选素材”里的文件。
            // 以审核条目的 source 为准补全导出输入，避免 task.clips 旧快照遗漏。
            const exportClips = [...(task.clips || [])];
            const exportClipKeys = new Set(exportClips.map(item => String(item || '').replace(/\\/g, '/').normalize('NFC')));
            reviewSegments.forEach(segment => {
                const source = String(segment.source || '');
                const key = source.replace(/\\/g, '/').normalize('NFC');
                if (source && !exportClipKeys.has(key)) {
                    exportClips.push(source);
                    exportClipKeys.add(key);
                }
            });
            exportStage = '调用自动剪辑导出接口';
            const outputName = sanitizeAutoEditBatchOutputName(task.outputName, task.name || `task_${index + 1}`);
            const outputDir = window.electronAPI.pathJoin(task.folder, '_auto_edit');
            const response=await apiFetch(`${API_BASE}/media/convert`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({files:exportClips,clips:exportClips,mode:'auto_edit',request_id:requestId,analysis_only:false,review_segments:reviewSegments,ignore_mismatch:true,force_mismatch:false,script_text:task.script,output_dir:outputDir,output_path:window.electronAPI.pathJoin(outputDir,`${outputName}.mp4`),...(task.settings||getAutoEditRequestSettings()),force_transcribe:false})});
            exportStage = '读取导出结果';
            const data=await response.json(); if(!response.ok) throw new Error(data.error||'导出失败');
            data.review_segments = reviewSegments.map(segment => ({ ...segment }));
            exportedData = data;
            task.reviewSegments = data.review_segments;
            task.result=data; task.status='exported'; task.message='导出完成（已记录）';
            task.exportSignature = autoEditBatchExportSignature(task);
            task.exportedAt = new Date().toISOString();
            task.reelsTransferError = '';
        } catch (e) {
            console.error(`[AutoEdit Batch Export] task=${task.name} stage=${exportStage}`, e);
            const cancelled = /任务已停止|已收到停止指令/.test(String(e?.message || ''));
            task.status = cancelled ? 'cancelled' : 'error';
            task.message = cancelled ? '已停止导出（未完成的输出已取消）' : `${exportStage}: ${e.message}`;
        }
        // “导出视频”和“送入 Reels”是两个独立步骤。Reels 页面接收失败时，
        if (exportedData && options.projectPath) {
            try {
                await saveAutoEditBatchReelsEntry(options.projectPath, task, index);
                task.message = '导出完成 · 已写入 Reels 任务工程';
            } catch (error) {
                task.message = `成片已完成，但工程保存失败：${error.message}`;
                options.onProjectError?.(error);
                showToast(task.message, 'error', 12000);
            }
        }
        // 不能把已经成功生成在磁盘上的视频误报为“导出失败”。
        if (exportedData && task.sendToReels !== false && document.getElementById('autoedit-send-reels')?.checked && options.deferReels !== true && options.skipReels !== true) {
            try {
                await sendAutoEditResultToReels(exportedData, { silent: true, navigate: false, baseName: task.outputName || task.name });
                task.message = '导出完成 · 已送入 Reels';
            } catch (e) {
                console.error(`[AutoEdit Batch Export] task=${task.name} stage=送入批量 Reels`, e);
                task.status = 'warning';
                task.reelsTransferError = e.message || String(e);
                task.message = `导出已完成 · Reels 接收失败`;
            }
        }
    } finally {
        autoEditActiveRequestIds.delete(requestId);
        if(typeof unsubscribe==='function')unsubscribe();
        if(ownsLock)setAutoEditBatchRunning(false);
        // 每完成一个任务立即落盘工作区。即使应用异常退出，已生成的成片、
        // 导出指纹和 Reels 发送状态也会在下次打开时用于跳过重复导出。
        saveAutoEditWorkspaceState?.();
        renderAutoEditBatchTasks();
    }
}
async function startAutoEditBatchExport(options = {}) {
    if(autoEditBatchRunning)return showToast('批量任务正在运行，请稍候','info');
    const ready=autoEditBatchTasks.map((task,index)=>({task,index})).filter(x=>x.task.sendToReels !== false && x.task.result?.analysis_only && !autoEditBatchExportIsCurrent(x.task));
    if(!ready.length) return showToast('没有需要重新导出的已勾选任务（已导出且未修改的任务已保留）','info');
    const risky=ready.filter(x=>(x.task.result.segments||[]).some(s=>s.status==='warning'));
    if(risky.length && !confirm(`${risky.length} 个任务仍有待审核项目。继续将按当前分析结果导出；建议先逐套审核。确定继续吗？`)) return;
    autoEditBatchStopRequested = false;
    setAutoEditBatchRunning(true);
    try {
        const shouldSendReels = options.skipReels !== true && document.getElementById('autoedit-send-reels')?.checked === true;
        // 并发数沿用“同时分析”设置（1–4）。每套仍在自身完成后立即送入
        // Reels 并持久化，不再等整批视频全部导完才集中发送；中断后可跳过
        // 已完成项。内存紧张时把该数设为 1 即可切换为最稳妥模式。
        const n = Math.max(1, Math.min(4, parseInt(document.getElementById('autoedit-batch-concurrency')?.value || '2', 10)));
        let cursor = 0;
        let projectError = null;
        const worker = async () => {
            while (!autoEditBatchStopRequested && cursor < ready.length && !projectError) {
                const { index } = ready[cursor++];
                await exportAutoEditBatchTask(index, {
                    managed: true,
                    deferReels: false,
                    skipReels: options.skipReels === true,
                    projectPath: options.projectPath,
                    onProjectError: error => { projectError = error; },
                });
                saveAutoEditWorkspaceState?.();
            }
        };
        await Promise.all(Array.from({ length: Math.min(n, ready.length) }, worker));
        if (autoEditBatchStopRequested) {
            showToast('批量导出已停止：未启动的任务不会继续导出。', 'warning');
            return;
        }
        if (options.projectPath) {
            showToast(projectError ? '工程保存失败，已停止领取后续任务；已完成视频仍保留' : `本轮结束，已完成任务逐套保存到：${options.projectPath}`, projectError ? 'error' : 'success', 12000);
            window.electronAPI?.showItemInFolder?.(options.projectPath);
        }
        const failed=ready.filter(x=>x.task.status==='error').length;
        const reelsFailed=ready.filter(x=>x.task.reelsTransferError).length;
        const summary = failed
            ? `批量导出完成，${failed} 个导出失败${reelsFailed ? `，${reelsFailed} 个 Reels 接收失败` : ''}`
            : (reelsFailed ? `视频全部导出完成，${reelsFailed} 个未送入 Reels` : '批量导出完成');
        showToast(summary,failed?'error':(reelsFailed?'info':'success'));
        // 单套交付期间不抢走当前导出界面；整批队列结束后再一次性打开 Reels。
        if (shouldSendReels && typeof openPanelByName === 'function') openPanelByName('batch-reels');
        if (shouldSendReels) playAutoEditBatchCompletionSound(failed === 0 && reelsFailed === 0);
    } finally { setAutoEditBatchRunning(false); }
}
function startAutoEditBatchExportOnly() {
    return startAutoEditBatchExport({ skipReels: true });
}
async function saveAutoEditBatchReelsEntry(projectPath, task, index) {
    const response = await window.electronAPI.apiCall('media/save-autoedit-batch-project', {
        projectPath, entry: { id: task.result.output_path, order: index, name: task.outputName || task.name,
            settings: task.settings || {}, exportedAt: task.exportedAt,
            result: task.result }
    });
    if (!response?.success) throw new Error(response?.error || '写入工程失败');
}
async function startAutoEditBatchExportProject() {
    if (autoEditBatchRunning || autoEditActiveRequestIds.size) return showToast('请等待当前任务完成', 'info');
    const selected = autoEditBatchTasks.filter(task => task.sendToReels !== false && task.result);
    if (!selected.length) return showToast('请先分析并勾选需要导出的任务', 'info');
    const folder = await window.electronAPI.selectDirectory(); if (!folder) return;
    const projectPath = window.electronAPI.pathJoin(folder, '自动剪辑批量任务.autoedit-batch.json');
    if (window.electronAPI.readFileText(projectPath) && !confirm('此目录已有批量工程。继续会合并任务，同一成片路径更新记录，其他旧任务保留。是否继续？')) return;
    try {
        // 已完成且未修改的任务无需重剪，也必须补入工程。
        for (const task of selected) if (autoEditBatchExportIsCurrent(task)) {
            await saveAutoEditBatchReelsEntry(projectPath, task, autoEditBatchTasks.indexOf(task));
        }
        await startAutoEditBatchExport({ skipReels: true, projectPath });
        showToast(`工程位置：${projectPath}。在批量 Reels 点击“加载自动剪辑批量工程”恢复；请保留原成片和字幕文件。`, 'info', 12000);
    } catch (error) { showToast(`工程保存失败：${error.message}`, 'error', 12000); }
}
let autoEditBatchProjectLoading = false;
async function loadAutoEditBatchReelsProject() {
    if (autoEditBatchProjectLoading) return;
    const paths = await window.electronAPI.selectFiles({ properties: ['openFile'], filters: [{ name: '自动剪辑批量工程', extensions: ['json'] }] });
    if (!paths?.length) return;
    autoEditBatchProjectLoading = true;
    try {
        const project = JSON.parse(await window.electronAPI.readFileText(paths[0]));
        if (project.type !== 'videokit-autoedit-batch' || project.version !== 1 || !Array.isArray(project.tasks)) throw new Error('不是支持的自动剪辑批量工程');
        if (!confirm(`加载 ${project.tasks.length} 个已完成任务到 Reels？成片采用路径引用，不复制视频。`)) return;
        let loaded = 0, failed = 0;
        for (const entry of project.tasks.slice().sort((a, b) => a.order - b.order)) {
            try {
                if (!entry.result?.output_path || !entry.result?.srt_path) throw new Error('缺少成片或字幕路径');
                showToast(`正在恢复 ${loaded + failed + 1}/${project.tasks.length}：${entry.name}`, 'info');
                await window.reelsCreateTaskFromAutoEditResult(entry.result, { baseName: entry.name, skipRecoveryCollection: true });
                loaded++;
            } catch (error) { failed++; console.warn('恢复任务失败', entry.name, error); }
        }
        showToast(`恢复完成：${loaded} 成功，${failed} 失败${failed ? '；请检查原成片和字幕是否仍在原路径' : ''}`, failed ? 'warning' : 'success', 10000);
    } catch (error) { showToast(`加载失败：${error.message}`, 'error'); }
    finally { autoEditBatchProjectLoading = false; }
}
function playAutoEditBatchCompletionSound(success = true) {
    try {
        const AudioContextClass = window.AudioContext || window.webkitAudioContext;
        if (!AudioContextClass) return;
        const context = new AudioContextClass();
        context.resume?.().catch(() => {});
        const tones = success ? [660, 880, 1040] : [520, 390];
        const start = context.currentTime + .03;
        tones.forEach((frequency, index) => {
            const oscillator = context.createOscillator();
            const gain = context.createGain();
            oscillator.frequency.value = frequency;
            oscillator.type = 'sine';
            gain.gain.setValueAtTime(.0001, start + index * .15);
            gain.gain.exponentialRampToValueAtTime(.14, start + index * .15 + .02);
            gain.gain.exponentialRampToValueAtTime(.0001, start + index * .15 + .13);
            oscillator.connect(gain); gain.connect(context.destination);
            oscillator.start(start + index * .15); oscillator.stop(start + index * .15 + .14);
        });
        setTimeout(() => context.close().catch(() => {}), 900);
    } catch (_) {}
}
function showAutoEditBatchOutput(index) {
    const outputPath = autoEditBatchTasks[index]?.result?.output_path;
    if (outputPath && window.electronAPI?.showItemInFolder) window.electronAPI.showItemInFolder(outputPath);
}
async function retryAutoEditBatchTaskToReels(index) {
    const task = autoEditBatchTasks[index];
    if (!task?.result?.output_path) return showToast('该任务还没有可用成片', 'error');
    if (autoEditBatchRunning) return showToast('批量任务正在运行，请稍候', 'info');
    setAutoEditBatchRunning(true);
    task.message = '正在重新送入 Reels';
    renderAutoEditBatchTasks();
    try {
        await sendAutoEditResultToReels(task.result, { silent: true, baseName: task.outputName || task.name });
        task.status = 'ready';
        task.reelsTransferError = '';
        task.message = '导出完成 · 已送入 Reels';
        showToast('已重新送入批量 Reels', 'success');
    } catch (error) {
        task.status = 'warning';
        task.reelsTransferError = error.message || String(error);
        task.message = '导出已完成 · Reels 接收失败';
        showToast(`Reels 接收失败：${escapeHtml(task.reelsTransferError)}`, 'error');
    }
    finally {
        setAutoEditBatchRunning(false);
        renderAutoEditBatchTasks();
    }
}
function openAutoEditBatchReview(index) {
    const task=autoEditBatchTasks[index]; if(!task?.result)return;
    autoEditCurrentFolder = task.folder || '';
    autoEditFiles=task.clips.map(path=>({path,name:path.split(/[/\\]/).pop(),status:'transcribed',manualSubtitlePath:task.manualSubtitleMap?.[path] || null}));
    document.getElementById('autoedit-script').value=task.script; updateAutoEditScriptCount(); renderAutoEditFiles();
    const savedReviews = Array.isArray(task.reviewSegments) ? task.reviewSegments : [];
    const originals = Array.isArray(task.result.segments) ? task.result.segments : [];
    const originalById = new Map(originals.map(segment => [segment.segment_id, segment]));
    const reviewById = new Map(savedReviews.filter(review => review?.segment_id).map(review => [review.segment_id, review]));
    const reviewBySource = new Map(savedReviews.filter(review => review?.source).map(review => [review.source, review]));
    const reviewResult = savedReviews.length ? {
        ...task.result,
        analysis_only: true,
        // 原分析片段是完整底稿；审核快照只覆盖改过的条目，绝不能把未改动的正常片段丢掉。
        segments: originals.map(original => ({
            ...original,
            ...(reviewById.get(original.segment_id) || reviewBySource.get(original.source) || {}),
        })).concat(savedReviews.filter(review => !originalById.has(review.segment_id) && !originals.some(original => original.source === review.source))),
    } : task.result;
    autoEditActiveBatchIndex=index; autoEditLastResult=reviewResult; autoEditOutputDir=task.result.output_dir||window.electronAPI.pathJoin(task.folder,'_auto_edit'); setAutoEditMode('single',true); renderAutoEditResult(reviewResult); document.getElementById('autoedit-result-section')?.classList.remove('hidden');
}

function openAutoEditBatchTimelineReview(index) {
    openAutoEditBatchReview(index);
    if (typeof openAutoEditTimelineReview === 'function') {
        setTimeout(() => {
            openAutoEditTimelineReview();
        }, 50);
    }
}
window.openAutoEditBatchTimelineReview = openAutoEditBatchTimelineReview;

let autoEditFiles = [];
let autoEditCurrentFolder = '';
let autoEditOutputDir = '';
let autoEditResultFiles = [];
let autoEditLastResult = null;
let autoEditProjectPersistTimer = null;
let autoEditProgressUnsubscribe = null;
const autoEditWorkspaces = [{ name: '单套任务 1', state: null }];
let autoEditWorkspaceIndex = 0;
function captureAutoEditWorkspace() {
    const fields = {};
    document.querySelectorAll('[id^="autoedit-"]').forEach(el => {
        if (['INPUT', 'SELECT', 'TEXTAREA'].includes(el.tagName) && el.type !== 'file') fields[el.id] = { value: el.value, checked: el.checked };
    });
    return { files: autoEditFiles, folder: autoEditCurrentFolder, outputDir: autoEditOutputDir,
        resultFiles: autoEditResultFiles, result: autoEditLastResult, tasks: autoEditBatchTasks,
        cells: autoEditBatchScriptCells, unmatched: autoEditBatchUnmatchedScripts,
        paired: autoEditBatchSmartPairingComplete, activeBatch: autoEditActiveBatchIndex,
        filter: autoEditBatchTaskFilter, fields,
        mode: document.getElementById('autoedit-batch-panel')?.style.display === 'none' ? 'single' : 'batch' };
}
function saveAutoEditWorkspaceState() {
    autoEditWorkspaces[autoEditWorkspaceIndex].state = captureAutoEditWorkspace();
    try {
        localStorage.setItem('videokit-autoedit-workspaces-v1', JSON.stringify({ index: autoEditWorkspaceIndex, workspaces: autoEditWorkspaces }));
        document.getElementById('autoedit-workspace-save-error')?.remove();
        return true;
    } catch (error) {
        console.warn('任务标签保存失败', error);
        if (!document.getElementById('autoedit-workspace-save-error')) {
            const warning = document.createElement('div');
            warning.id = 'autoedit-workspace-save-error'; warning.setAttribute('role', 'alert');
            warning.style.cssText = 'color:#fca5a5;background:#451a1a;padding:10px;border:1px solid #ef4444;border-radius:6px';
            warning.textContent = '任务标签保存失败（可能是本地存储已满）。当前数据仍在内存中，上次成功保存的记录未被删除；关闭软件前请保存分析工程。';
            document.getElementById('autoedit-workspace-tabs')?.after(warning);
            showToast(warning.textContent, 'error', 12000);
        }
        return false;
    }
}
function switchAutoEditWorkspace(index, createMode) {
    if (autoEditBatchRunning || autoEditActiveRequestIds.size) return showToast('当前标签正在处理，请完成或停止后切换；各标签数据独立保存', 'info');
    if (document.querySelector('.autoedit-review-row')) persistAutoEditBatchReview();
    saveAutoEditWorkspaceState();
    if (createMode) {
        index = autoEditWorkspaces.length;
        autoEditWorkspaces.push({ name: `${createMode === 'batch' ? '批量' : '单套'}任务 ${index + 1}`, state: { mode: createMode } });
    }
    if (!autoEditWorkspaces[index]) return;
    document.getElementById('autoedit-timeline-review-modal')?.remove();
    autoEditWorkspaceIndex = index;
    const state = autoEditWorkspaces[index].state || {};
    autoEditFiles = state.files || []; autoEditCurrentFolder = state.folder || '';
    autoEditOutputDir = state.outputDir || ''; autoEditResultFiles = state.resultFiles || [];
    autoEditLastResult = state.result || null; autoEditBatchTasks = state.tasks || [];
    autoEditBatchScriptCells = state.cells || []; autoEditBatchUnmatchedScripts = state.unmatched || [];
    autoEditBatchSmartPairingComplete = state.paired || false;
    autoEditActiveBatchIndex = state.activeBatch ?? -1; autoEditBatchTaskFilter = state.filter || 'all';
    for (const id of ['autoedit-script', 'autoedit-batch-paste', 'autoedit-batch-output-names']) {
        const el = document.getElementById(id); if (el) el.value = '';
    }
    Object.entries(state.fields || {}).forEach(([id, field]) => {
        const el = document.getElementById(id); if (!el) return;
        el.value = field.value; if (el.type === 'checkbox') el.checked = field.checked;
    });
    setAutoEditMode(state.mode || 'single', true); renderAutoEditFiles();
    if (autoEditLastResult) renderAutoEditResult(autoEditLastResult);
    document.getElementById('autoedit-result-section')?.classList.toggle('hidden', !autoEditLastResult);
    renderAutoEditWorkspaceTabs(); saveAutoEditWorkspaceState();
}
function renderAutoEditWorkspaceTabs() {
    let root = document.getElementById('autoedit-workspace-tabs');
    if (!root) {
        root = document.createElement('div'); root.id = 'autoedit-workspace-tabs';
        root.style.cssText = 'display:flex;gap:8px;flex-wrap:wrap;margin:12px 0';
        document.getElementById('autoedit-mode-single')?.parentElement.after(root);
    }
    root.replaceChildren();
    autoEditWorkspaces.forEach((workspace, index) => {
        const button = document.createElement('button'); button.textContent = workspace.name;
        button.className = `btn ${index === autoEditWorkspaceIndex ? 'btn-primary' : 'btn-secondary'}`;
        button.onclick = () => switchAutoEditWorkspace(index); root.append(button);
        if (autoEditWorkspaces.length > 1) {
            const close = document.createElement('button'); close.className = 'btn btn-secondary';
            close.textContent = '×'; close.setAttribute('aria-label', `关闭 ${workspace.name}`);
            close.onclick = () => closeAutoEditWorkspaceTab(index); root.append(close);
        }
    });
    for (const mode of ['single', 'batch']) {
        const button = document.createElement('button'); button.className = 'btn btn-secondary';
        button.textContent = mode === 'single' ? '＋ 单套标签' : '＋ 批量标签';
        button.onclick = () => switchAutoEditWorkspace(-1, mode); root.append(button);
    }
}
function closeAutoEditWorkspaceTab(index) {
    if (autoEditBatchRunning || autoEditActiveRequestIds.size) return showToast('请完成或停止任务后关闭标签', 'info');
    if (!autoEditWorkspaces[index] || autoEditWorkspaces.length <= 1) return;
    if (!confirm(`关闭“${autoEditWorkspaces[index].name}”？该标签将从保存列表中移除，不会删除原素材或已导出的文件。`)) return;
    if (index === autoEditWorkspaceIndex) switchAutoEditWorkspace(index === 0 ? 1 : index - 1);
    autoEditWorkspaces.splice(index, 1);
    if (autoEditWorkspaceIndex > index) autoEditWorkspaceIndex--;
    renderAutoEditWorkspaceTabs(); saveAutoEditWorkspaceState();
}
window.addEventListener('DOMContentLoaded', () => {
    renderAutoEditWorkspaceTabs();
    // 明确恢复入口，避免启动时覆盖应用已有的项目恢复流程。
    const saved = localStorage.getItem('videokit-autoedit-workspaces-v1');
    if (saved) {
        const button = document.createElement('button'); button.className = 'btn btn-secondary'; button.textContent = '恢复上次任务标签';
        button.onclick = () => {
            if (autoEditBatchRunning || autoEditActiveRequestIds.size) return;
            if (!confirm('恢复上次保存的标签？当前未保存的工作请先导出项目。')) return;
            try {
                const data = JSON.parse(saved);
                if (!Array.isArray(data.workspaces) || !data.workspaces.length) return;
                autoEditWorkspaces.splice(0, autoEditWorkspaces.length, ...data.workspaces);
                // 临时快照位置避免切换函数覆盖要恢复的标签。
                autoEditWorkspaceIndex = autoEditWorkspaces.length;
                autoEditWorkspaces.push({ name: '当前会话', state: null });
                switchAutoEditWorkspace(Math.min(data.index || 0, autoEditWorkspaces.length - 2));
            } catch (error) { showToast(`恢复失败：${error.message}`, 'error'); }
        };
        document.getElementById('autoedit-workspace-tabs')?.append(button);
    }
});
window.addEventListener('beforeunload', saveAutoEditWorkspaceState);

