async function sendAutoEditResultToReels(result = null, options = {}) {
    const data = result || autoEditLastResult;
    if (data?.analysis_only || !data?.output_path || !data?.srt_path) {
        if (data?.analysis_only && !options.silent) {
            const shouldExport = confirm('当前任务还处于“审核时间线”阶段，尚未生成成片视频与字幕。\n\n是否立即按当前审核结果正式导出并自动送入批量 Reels？');
            if (shouldExport) {
                return exportReviewedAutoEdit();
            }
            return;
        }
        const error = new Error('还没有可送入批量 Reels 的成片结果，请先按审核结果完成正式导出');
        if (!options.silent) showToast(error.message, 'warning');
        throw error;
    }
    if (typeof window.reelsCreateTaskFromAutoEditResult !== 'function') {
        const error = new Error('批量 Reels 接收功能未加载');
        if (!options.silent) showToast('批量 Reels 接收功能未加载，请先打开批量 Reels 页面后再试', 'error');
        throw error;
    }

    try {
        const task = await window.reelsCreateTaskFromAutoEditResult(data, { baseName: options.baseName });
        // 将 Reels 任务 ID 写回本次自动剪辑结果。后续从审核重新导出后，
        // 可用“更新已关联 Reels 任务”直接替换成片，而不是重复创建任务。
        if (task?.id) data.reels_task_id = task.id;
        // 批量队列在后台交付任务时保持当前页面，避免每完成一套就打断
        // 导出进度；用户手动“送入 Reels”仍沿用默认的页面跳转。
        if (options.navigate !== false && typeof openPanelByName === 'function') openPanelByName('batch-reels');
        if (!options.silent) {
            showToast(`已送入批量 Reels: ${task?.fileName || '自动剪辑任务'}`, 'success');
        }
    } catch (error) {
        if (!options.silent) showToast(`送入批量 Reels 失败: ${escapeHtml(error.message)}`, 'error');
        throw error;
    }
}

async function updateAutoEditResultInReels() {
    const data = autoEditLastResult;
    if (data?.analysis_only || !data?.output_path || !data?.srt_path) return showToast('请先按审核结果完成正式导出', 'warning');
    if (typeof window.reelsUpdateTaskFromAutoEditResult !== 'function') return showToast('请先打开一次批量 Reels 页面后再更新', 'warning');
    try {
        const task = await window.reelsUpdateTaskFromAutoEditResult(data, { taskId: data.reels_task_id, replaceSubtitles: true, userInitiated: true });
        data.reels_task_id = task.id;
        if (typeof openPanelByName === 'function') openPanelByName('batch-reels');
        showToast('已更新关联 Reels 任务；覆层、贴纸、BGM 与样式已保留', 'success');
    } catch (error) {
        showToast(`没有找到关联任务：${error.message || error}。请先用“送入批量 Reels”创建一次。`, 'warning');
    }
}
window.updateAutoEditResultInReels = updateAutoEditResultInReels;

